//! Regular expression matcher built on top of `regex-syntax` and
//! `regex-automata`, mimicking the semantics of a line oriented grep tool
//! (line terminators are not allowed to be matched unless multiline mode is
//! enabled, smart case, word boundaries, fixed strings, ...).

use std::fmt;

use regex_automata::meta;
use regex_automata::util::captures::Captures;
use regex_automata::{Anchored, Input};
use regex_syntax::ast::{self, Ast};
use regex_syntax::hir::{self, Hir, HirKind, Look};

/// Error that may occur while building a matcher.
pub struct Error {
    kind: ErrorKind,
}

impl fmt::Debug for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Error").field("kind", &self.kind).finish()
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.kind {
            ErrorKind::Regex(msg) => write!(f, "{}", msg),
            ErrorKind::NotAllowed(lit) => {
                write!(f, "the literal {:?} is not allowed in a regex", lit)
            }
            ErrorKind::InvalidLineTerminator(byte) => {
                write!(f, "line terminators must be ASCII, but {:?} is not", byte)
            }
        }
    }
}

impl std::error::Error for Error {}

#[derive(Debug)]
enum ErrorKind {
    Regex(String),
    NotAllowed(String),
    InvalidLineTerminator(u8),
}

impl Error {
    fn regex<E: fmt::Display>(err: E) -> Error {
        Error { kind: ErrorKind::Regex(err.to_string()) }
    }
}

/// Configuration of the matcher.
#[derive(Clone, Debug, Default)]
pub struct MatcherConfig {
    pub case_insensitive: bool,
    pub case_smart: bool,
    pub word: bool,
    pub fixed_strings: bool,
    pub multiline: bool,
}

impl MatcherConfig {
    fn line_terminator(&self) -> Option<u8> {
        if self.multiline {
            None
        } else {
            Some(b'\n')
        }
    }
}

/// Analysis of the parsed pattern used to implement smart case.
#[derive(Default)]
struct AstAnalysis {
    any_uppercase: bool,
    any_literal: bool,
}

impl AstAnalysis {
    fn from_ast(ast: &Ast) -> AstAnalysis {
        let mut analysis = AstAnalysis::default();
        analysis.visit(ast);
        analysis
    }

    fn done(&self) -> bool {
        self.any_uppercase && self.any_literal
    }

    fn visit(&mut self, ast: &Ast) {
        if self.done() {
            return;
        }
        match ast {
            Ast::Empty(_)
            | Ast::Flags(_)
            | Ast::Dot(_)
            | Ast::Assertion(_)
            | Ast::ClassUnicode(_)
            | Ast::ClassPerl(_) => {}
            Ast::Literal(lit) => self.visit_literal(lit),
            Ast::ClassBracketed(class) => self.visit_class_set(&class.kind),
            Ast::Repetition(rep) => self.visit(&rep.ast),
            Ast::Group(group) => self.visit(&group.ast),
            Ast::Alternation(alt) => {
                for sub in &alt.asts {
                    self.visit(sub);
                }
            }
            Ast::Concat(concat) => {
                for sub in &concat.asts {
                    self.visit(sub);
                }
            }
        }
    }

    fn visit_class_set(&mut self, set: &ast::ClassSet) {
        match set {
            ast::ClassSet::Item(item) => self.visit_class_set_item(item),
            ast::ClassSet::BinaryOp(op) => {
                self.visit_class_set(&op.lhs);
                self.visit_class_set(&op.rhs);
            }
        }
    }

    fn visit_class_set_item(&mut self, item: &ast::ClassSetItem) {
        match item {
            ast::ClassSetItem::Empty(_)
            | ast::ClassSetItem::Ascii(_)
            | ast::ClassSetItem::Unicode(_)
            | ast::ClassSetItem::Perl(_) => {}
            ast::ClassSetItem::Literal(lit) => self.visit_literal(lit),
            ast::ClassSetItem::Range(range) => {
                self.visit_literal(&range.start);
                self.visit_literal(&range.end);
            }
            ast::ClassSetItem::Bracketed(class) => self.visit_class_set(&class.kind),
            ast::ClassSetItem::Union(union) => {
                for sub in &union.items {
                    self.visit_class_set_item(sub);
                }
            }
        }
    }

    fn visit_literal(&mut self, lit: &ast::Literal) {
        self.any_literal = true;
        self.any_uppercase = self.any_uppercase || lit.c.is_uppercase();
    }
}

/// Build a HIR for the given pattern according to the configuration.
fn build_hir(config: &MatcherConfig, pattern: &str, allow_fixed: bool) -> Result<Hir, Error> {
    let pattern = if config.fixed_strings && allow_fixed {
        format!("(?:{})", regex_syntax::escape(pattern))
    } else {
        format!("(?:{})", pattern)
    };
    let ast = ast::parse::ParserBuilder::new()
        .nest_limit(250)
        .octal(false)
        .ignore_whitespace(false)
        .build()
        .parse(&pattern)
        .map_err(Error::regex)?;
    let analysis = AstAnalysis::from_ast(&ast);
    let case_insensitive =
        config.case_insensitive || (config.case_smart && !analysis.any_uppercase);
    let hir = hir::translate::TranslatorBuilder::new()
        .utf8(false)
        .case_insensitive(case_insensitive)
        .multi_line(true)
        .dot_matches_new_line(false)
        .crlf(false)
        .swap_greed(false)
        .unicode(true)
        .build()
        .translate(&pattern, &ast)
        .map_err(Error::regex)?;
    match config.line_terminator() {
        None => Ok(hir),
        Some(byte) => strip_from_match(hir, byte),
    }
}

/// Returns a new HIR that is guaranteed to never match the given byte.
fn strip_from_match(expr: Hir, byte: u8) -> Result<Hir, Error> {
    if byte > 0x7F {
        return Err(Error { kind: ErrorKind::InvalidLineTerminator(byte) });
    }
    let chr = char::from(byte);
    let not_allowed = || Error { kind: ErrorKind::NotAllowed(chr.to_string()) };
    let hir = match expr.into_kind() {
        HirKind::Empty => Hir::empty(),
        HirKind::Literal(hir::Literal(lit)) => {
            if lit.iter().any(|&b| b == byte) {
                return Err(not_allowed());
            }
            Hir::literal(lit)
        }
        HirKind::Class(hir::Class::Unicode(mut cls)) => {
            if cls.ranges().is_empty() {
                return Ok(Hir::class(hir::Class::Unicode(cls)));
            }
            let remove = hir::ClassUnicode::new(Some(hir::ClassUnicodeRange::new(chr, chr)));
            cls.difference(&remove);
            if cls.ranges().is_empty() {
                return Err(not_allowed());
            }
            Hir::class(hir::Class::Unicode(cls))
        }
        HirKind::Class(hir::Class::Bytes(mut cls)) => {
            if cls.ranges().is_empty() {
                return Ok(Hir::class(hir::Class::Bytes(cls)));
            }
            let remove = hir::ClassBytes::new(Some(hir::ClassBytesRange::new(byte, byte)));
            cls.difference(&remove);
            if cls.ranges().is_empty() {
                return Err(not_allowed());
            }
            Hir::class(hir::Class::Bytes(cls))
        }
        HirKind::Look(look) => Hir::look(look),
        HirKind::Repetition(mut rep) => {
            rep.sub = Box::new(strip_from_match(*rep.sub, byte)?);
            Hir::repetition(rep)
        }
        HirKind::Capture(mut cap) => {
            cap.sub = Box::new(strip_from_match(*cap.sub, byte)?);
            Hir::capture(cap)
        }
        HirKind::Concat(subs) => {
            let subs = subs
                .into_iter()
                .map(|sub| strip_from_match(sub, byte))
                .collect::<Result<Vec<Hir>, Error>>()?;
            Hir::concat(subs)
        }
        HirKind::Alternation(subs) => {
            let subs = subs
                .into_iter()
                .map(|sub| strip_from_match(sub, byte))
                .collect::<Result<Vec<Hir>, Error>>()?;
            Hir::alternation(subs)
        }
    };
    Ok(hir)
}

/// Renumber capture groups so that a new outer group can take index 1.
fn renumber_captures(expr: Hir) -> Hir {
    match expr.into_kind() {
        HirKind::Empty => Hir::empty(),
        HirKind::Literal(hir::Literal(lit)) => Hir::literal(lit),
        HirKind::Class(cls) => Hir::class(cls),
        HirKind::Look(look) => Hir::look(look),
        HirKind::Repetition(mut rep) => {
            rep.sub = Box::new(renumber_captures(*rep.sub));
            Hir::repetition(rep)
        }
        HirKind::Capture(mut cap) => {
            cap.index += 1;
            cap.sub = Box::new(renumber_captures(*cap.sub));
            Hir::capture(cap)
        }
        HirKind::Concat(subs) => Hir::concat(subs.into_iter().map(renumber_captures).collect()),
        HirKind::Alternation(subs) => {
            Hir::alternation(subs.into_iter().map(renumber_captures).collect())
        }
    }
}

fn compile(hir: &Hir) -> Result<meta::Regex, Error> {
    meta::Builder::new()
        .configure(meta::Config::new().utf8_empty(false))
        .build_from_hir(hir)
        .map_err(Error::regex)
}

