use std::cmp::Ordering;
use std::fs::Metadata;
use std::path::Path;
use std::time::SystemTime;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SortKey {
    Path,
    Modified,
    Created,
    Accessed,
}

impl SortKey {
    pub fn from_name(name: &str) -> SortKey {
        match name {
            "modified" => SortKey::Modified,
            "created" => SortKey::Created,
            "accessed" => SortKey::Accessed,
            _ => SortKey::Path,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SortMode {
    pub key: SortKey,
    pub reverse: bool,
}

impl SortMode {
    pub fn new(name: &str, reverse: bool) -> SortMode {
        SortMode { key: SortKey::from_name(name), reverse }
    }

    /// Configure the walker to produce entries in the requested order.
    pub fn configure(self, builder: &mut ignore::WalkBuilder) {
        let reverse = self.reverse;
        match self.key {
            SortKey::Path => {
                if reverse {
                    builder.sort_by_file_name(|a, b| a.cmp(b).reverse());
                } else {
                    builder.sort_by_file_name(|a, b| a.cmp(b));
                }
            }
            SortKey::Modified => {
                builder.sort_by_file_path(move |a, b| {
                    sort_by_metadata_time(a, b, reverse, |md| md.modified())
                });
            }
            SortKey::Created => {
                builder.sort_by_file_path(move |a, b| {
                    sort_by_metadata_time(a, b, reverse, |md| md.created())
                });
            }
            SortKey::Accessed => {
                builder.sort_by_file_path(move |a, b| {
                    sort_by_metadata_time(a, b, reverse, |md| md.accessed())
                });
            }
        }
    }
}

fn sort_by_metadata_time<G>(p1: &Path, p2: &Path, reverse: bool, get_time: G) -> Ordering
where
    G: Fn(&Metadata) -> std::io::Result<SystemTime>,
{
    let t1 = p1.metadata().and_then(|md| get_time(&md));
    let t2 = p2.metadata().and_then(|md| get_time(&md));
    match (t1, t2) {
        (Ok(t1), Ok(t2)) => {
            if reverse {
                t1.cmp(&t2).reverse()
            } else {
                t1.cmp(&t2)
            }
        }
        (Ok(_), Err(_)) => Ordering::Less,
        (Err(_), Ok(_)) => Ordering::Greater,
        (Err(_), Err(_)) => Ordering::Equal,
    }
}
