    let mut buf: Vec<u8> = vec![0; DEFAULT_BUFFER_CAPACITY];
    let mut pos = 0usize;
    let mut end = 0usize;
    let mut line_number: u64 = 1;

    loop {
        // Roll unconsumed bytes to the front of the buffer.
        buf.copy_within(pos..end, 0);
        end -= pos;
        pos = 0;

        // Fill until a line terminator (or EOF) is found.
        let last_lineterm;
        loop {
            if end == buf.len() {
                let len = std::cmp::max(1, buf.len());
                buf.resize(len + len * 2, 0);
            }
            let readlen = rdr.read(&mut buf[end..])?;
            if readlen == 0 {
                last_lineterm = end;
                break;
            }
            let oldend = end;
            end += readlen;
            if memchr::memchr(BINARY_BYTE, &buf[oldend..end]).is_some() {
                // Binary data detected: stop searching this file.
                return Ok(matches);
            }
            if let Some(i) = memchr::memrchr(b'\n', &buf[oldend..end]) {
                last_lineterm = oldend + i + 1;
                break;
            }
        }
        if end == 0 {
            break;
        }

        // Search all complete lines.
        while pos < last_lineterm {
            let line_end = match memchr::memchr(b'\n', &buf[pos..last_lineterm]) {
                Some(i) => pos + i + 1,
                None => last_lineterm,
            };
            let line = &buf[pos..line_end];
            let content = strip_terminator(line);
            let ranges = matcher.find_all(content);
            if !ranges.is_empty() {
                let text = match std::str::from_utf8(content) {
                    Ok(text) => text,
                    Err(_) => return Ok(matches),
                };
                matches.push(Match::new(line_number, text.to_string(), ranges));
            }
            if line.ends_with(b"\n") {
                line_number += 1;
            }
            pos = line_end;
        }
        if last_lineterm == end && pos == end {
            // Everything consumed; check whether there is more data.
            let mut probe = [0u8; 1];
            let n = rdr.read(&mut probe)?;
            if n == 0 {
                break;
            }
            if end == buf.len() {
                let len = std::cmp::max(1, buf.len());
                buf.resize(len + len * 2, 0);
            }
            buf[end] = probe[0];
            if probe[0] == BINARY_BYTE {
                return Ok(matches);
            }
            end += 1;
        }
    }
    Ok(matches)
}

fn strip_terminator(line: &[u8]) -> &[u8] {
    if line.ends_with(b"\n") {
        &line[..line.len() - 1]
    } else {
        line
    }
}

/// Multiline search: the whole file is read into memory.
fn search_multiline<R: Read>(rdr: &mut R, matcher: &Matcher) -> std::io::Result<Vec<Match>> {
    let mut slice = Vec::new();
    rdr.read_to_end(&mut slice)?;
    let mut matches = Vec::new();

    let binary_upto = std::cmp::min(slice.len(), DEFAULT_BUFFER_CAPACITY);
    if memchr::memchr(BINARY_BYTE, &slice[..binary_upto]).is_some() {
        return Ok(matches);
    }

    let mut pos = 0usize;
    let mut last_block: Option<(usize, usize)> = None;
    let mut all_ranges: Vec<(usize, usize)> = Vec::new();
    let mut line_counter = LineCounter::default();

    loop {
        let found = if pos <= slice.len() { matcher.find_at(&slice, pos) } else { None };
        let Some((start, end)) = found else {
            break;
        };
        all_ranges.push((start, end));
        pos = end;
        if start == end && pos < slice.len() {
            pos += 1;
        }
        let line = locate(&slice, (start, end));
        match last_block.take() {
            None => last_block = Some(line),
            Some(last) => {
                if last.1 >= line.0 {
                    last_block = Some((last.0, line.1));
                } else {
                    last_block = Some(line);
                    if !sink_block(&slice, last, &all_ranges, &mut line_counter, &mut matches) {
                        return Ok(matches);
                    }
                }
            }
        }
        if start == end && end >= slice.len() {
            break;
        }
    }
    if let Some(last) = last_block.take() {
        sink_block(&slice, last, &all_ranges, &mut line_counter, &mut matches);
    }
    Ok(matches)
}

#[derive(Default)]
struct LineCounter {
    pos: usize,
    line_number: u64,
}

impl LineCounter {
    fn line_number_at(&mut self, slice: &[u8], offset: usize) -> u64 {
        if offset < self.pos {
            self.pos = 0;
            self.line_number = 0;
        }
        self.line_number += memchr::memchr_iter(b'\n', &slice[self.pos..offset]).count() as u64;
        self.pos = offset;
        self.line_number + 1
    }
}

/// Find the range of the lines containing the given match.
fn locate(bytes: &[u8], (start, end): (usize, usize)) -> (usize, usize) {
    let line_start = memchr::memrchr(b'\n', &bytes[..start]).map_or(0, |i| i + 1);
    let line_end = if end > line_start && bytes[end - 1] == b'\n' {
        end
    } else {
        memchr::memchr(b'\n', &bytes[end..]).map_or(bytes.len(), |i| end + i + 1)
    };
    (line_start, line_end)
}

/// Report a block of matched lines. Returns false if searching should stop.
fn sink_block(
    slice: &[u8],
    (block_start, block_end): (usize, usize),
    ranges: &[(usize, usize)],
    counter: &mut LineCounter,
    matches: &mut Vec<Match>,
) -> bool {
    if block_start >= block_end {
        return false;
    }
    let block = &slice[block_start..block_end];
    if memchr::memchr(BINARY_BYTE, block).is_some() {
        return false;
    }
    if std::str::from_utf8(block).is_err() {
        return false;
    }
    let mut line_number = counter.line_number_at(slice, block_start);
    let mut line_start = block_start;
    while line_start < block_end {
        let line_end = match memchr::memchr(b'\n', &slice[line_start..block_end]) {
            Some(i) => line_start + i + 1,
            None => block_end,
        };
        let content = strip_terminator(&slice[line_start..line_end]);
        let content_end = line_start + content.len();
        let mut line_ranges = Vec::new();
        for &(s, e) in ranges {
            let s2 = std::cmp::max(s, line_start);
            let e2 = std::cmp::min(e, content_end);
            if s2 < e2 {
                line_ranges.push((s2 - line_start, e2 - line_start));
            }
        }
        let text = String::from_utf8_lossy(content).into_owned();
        matches.push(Match::new(line_number, text, line_ranges));
        line_number += 1;
        line_start = line_end;
    }
    true
}
