use std::sync::mpsc::{self, Receiver, TryRecvError};

pub use entries::{FileEntry, Match};
pub use search_config::SearchConfig;
use searcher::{Event, Searcher};
use sort::{SortKey, SortMode};

/// State of the application.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum State {
    Idle,
    Searching,
    OpenFile(bool),
    Error(String),
    Exit,
}

/// Core of the application: owns the search configuration, the background
/// searcher and the state machine.
pub struct Ig {
    config: SearchConfig,
    searcher: Searcher,
    rx: Receiver<Event>,
    state: State,
    search_id: u64,
}

impl Ig {
    pub fn new(config: SearchConfig) -> Ig {
        let (tx, rx) = mpsc::channel();
        Ig {
            config,
            searcher: Searcher::new(tx),
            rx,
            state: State::Idle,
            search_id: 0,
        }
    }

    pub fn state(&self) -> &State {
        &self.state
    }

    pub fn is_idle(&self) -> bool {
        self.state == State::Idle
    }

    pub fn is_searching(&self) -> bool {
        self.state == State::Searching
    }

    pub fn should_exit(&self) -> bool {
        self.state == State::Exit
    }

    pub fn exit(&mut self) {
        self.state = State::Exit;
    }

    pub fn pattern(&self) -> &str {
        &self.config.pattern
    }

    pub fn set_pattern(&mut self, pattern: String) {
        self.config.pattern = pattern;
    }

    pub fn sort_mode(&self) -> Option<SortMode> {
        self.config.sort
    }

    /// Toggle sorting by the given key: same key flips the direction, a new
    /// key starts with ascending order.
    pub fn set_sort_key(&mut self, key: SortKey) {
        let reverse = match self.config.sort {
            Some(mode) if mode.key == key => !mode.reverse,
            _ => false,
        };
        self.config.sort = Some(SortMode { key, reverse });
    }

    /// Start a new search (only possible while idle).
    pub fn search(&mut self) -> bool {
        if self.state != State::Idle {
            return false;
        }
        self.state = State::Searching;
        self.search_id += 1;
        self.searcher.search(self.config.clone(), self.search_id);
        true
    }

    pub fn open_file(&mut self) {
        self.state = State::OpenFile(self.state == State::Idle);
    }

    /// Called after an attempt to open the editor.
    pub fn file_opened(&mut self, result: Result<(), String>) {
        if let State::OpenFile(idle) = self.state.clone() {
            match result {
                Ok(()) => {
                    self.state = if idle { State::Idle } else { State::Searching };
                }
                Err(message) => self.state = State::Error(message),
            }
        }
    }

    /// Poll the searcher for new events. Returns new file entries.
    pub fn handle_searcher_events(&mut self) -> Vec<FileEntry> {
        let mut entries = Vec::new();
        loop {
            match self.rx.try_recv() {
                Ok(Event::NewEntry(id, entry)) => {
                    if id == self.search_id {
                        entries.push(entry);
                    }
                }
                Ok(Event::SearchingFinished(id)) => {
                    if id == self.search_id && self.state == State::Searching {
                        self.state = State::Idle;
                    }
                }
                Ok(Event::Error(id)) => {
                    if id == self.search_id {
                        self.state = State::Exit;
                    }
                }
                Err(TryRecvError::Empty) | Err(TryRecvError::Disconnected) => break,
            }
        }
        entries
    }
}
