//! Resolution of the command used to open the selected match.

use std::process::Command;

use anyhow::{anyhow, bail, Context, Result};

use crate::args::{Args, EDITOR_VARIANTS};

const FILE_NAME_TOKEN: &str = "{file_name}";
const LINE_NUMBER_TOKEN: &str = "{line_number}";

/// Command template used to open a file at a given line.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EditorCommand {
    program: String,
    args: Vec<String>,
}

impl EditorCommand {
    pub fn from_args(args: &Args) -> Result<EditorCommand> {
        if let Some(custom) = &args.custom_command {
            return EditorCommand::parse_custom(custom)
                .with_context(|| format!("Incorrect editor command: '{}'", custom));
        }
        if let Some(editor) = &args.editor {
            return Ok(EditorCommand::from_variant(editor)
                .ok_or_else(|| anyhow!("invalid variant: {}", editor))?);
        }
        for var in ["IGREP_EDITOR", "VISUAL", "EDITOR"] {
            if let Ok(value) = std::env::var(var) {
                let name = value.rsplit('/').next().unwrap_or("");
                return EditorCommand::from_variant(name)
                    .ok_or_else(|| anyhow!("invalid variant: {}", name))
                    .with_context(|| {
                        format!(
                            "\"{}\" read from ${}, possible variants: [{}]",
                            value,
                            var,
                            EDITOR_VARIANTS.join(", ")
                        )
                    });
            }
        }
        Ok(EditorCommand::from_variant("vim").expect("default editor"))
    }

    fn from_variant(name: &str) -> Option<EditorCommand> {
        let (program, args): (&str, &[&str]) = match name {
            "vim" => ("vim", &["+{line_number}", "{file_name}"]),
            "neovim" | "nvim" => ("nvim", &["+{line_number}", "{file_name}"]),
            "nano" => ("nano", &["+{line_number}", "{file_name}"]),
            "code" | "vscode" => ("code", &["-g", "{file_name}:{line_number}"]),
            "code-insiders" => ("code-insiders", &["-g", "{file_name}:{line_number}"]),
            "emacs" => ("emacs", &["-nw", "+{line_number}", "{file_name}"]),
            "emacsclient" => ("emacsclient", &["-nw", "+{line_number}", "{file_name}"]),
            "hx" => ("hx", &["{file_name}:{line_number}"]),
            "helix" => ("helix", &["{file_name}:{line_number}"]),
            "subl" | "sublime-text" => ("subl", &["{file_name}:{line_number}"]),
            "micro" => ("micro", &["+{line_number}", "{file_name}"]),
            "intellij" => ("idea", &["--line", "{line_number}", "{file_name}"]),
            "goland" => ("goland", &["--line", "{line_number}", "{file_name}"]),
            "pycharm" => ("pycharm", &["--line", "{line_number}", "{file_name}"]),
            "less" => ("less", &["+{line_number}", "{file_name}"]),
            "fresh" => ("fresh", &["{file_name}:{line_number}"]),
            _ => return None,
        };
        Some(EditorCommand {
            program: program.to_string(),
            args: args.iter().map(|s| s.to_string()).collect(),
        })
    }

    fn parse_custom(command: &str) -> Result<EditorCommand> {
        let mut parts = command.split(' ');
        let program = parts.next().unwrap_or("");
        let args: Vec<String> = parts.map(|s| s.to_string()).collect();
        if args.is_empty() {
            bail!("Expected program and its arguments");
        }
        for token in [FILE_NAME_TOKEN, LINE_NUMBER_TOKEN] {
            let occurrences: usize = args.iter().map(|a| a.matches(token).count()).sum();
            if occurrences != 1 {
                bail!("Expected one occurrence of '{}'.", token);
            }
        }
        Ok(EditorCommand { program: program.to_string(), args })
    }

    pub fn program(&self) -> &str {
        &self.program
    }

    /// Build the process command for the given file and line.
    pub fn command(&self, file_name: &str, line_number: u64) -> Command {
        let mut cmd = Command::new(&self.program);
        for arg in &self.args {
            cmd.arg(
                arg.replace(FILE_NAME_TOKEN, file_name)
                    .replace(LINE_NUMBER_TOKEN, &line_number.to_string()),
            );
        }
        cmd
    }
}
