            if occurrences != 1 {
                bail!("Expected one occurrence of '{}'.", token);
            }
        }
        Ok(EditorCommand { program: program.to_string(), args })
    }

    pub fn program(&self) -> &str {
        &self.program
    }

    /// Build the process command for the given file and line.
    pub fn command(&self, file_name: &str, line_number: u64) -> Command {
        let mut cmd = Command::new(&self.program);
        for arg in &self.args {
            cmd.arg(
                arg.replace(FILE_NAME_TOKEN, file_name)
                    .replace(LINE_NUMBER_TOKEN, &line_number.to_string()),
            );
        }
        cmd
    }
}
