use ratatui::layout::Rect;
use ratatui::style::Style;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, List, ListItem, ListState};
use ratatui::Frame;

use super::theme::Theme;
use crate::ig::FileEntry;

/// List of search results grouped by file.
#[derive(Default)]
pub struct ResultList {
    entries: Vec<FileEntry>,
    file_idx: usize,
    match_idx: usize,
    /// Total number of matches reported by the searcher.
    total_matches: usize,
    /// Total number of files reported by the searcher.
    total_files: usize,
    filtered_matches: usize,
    state: ListState,
}

impl ResultList {
    pub fn clear(&mut self) {
        *self = ResultList::default();
    }

    pub fn add_entry(&mut self, entry: FileEntry) {
        self.total_matches += entry.matches.len();
        self.total_files += 1;
        self.entries.push(entry);
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn total_matches(&self) -> usize {
        self.total_matches
    }

    pub fn total_files(&self) -> usize {
        self.total_files
    }

    pub fn filtered_matches(&self) -> usize {
        self.filtered_matches
    }

    /// Number of currently visible matches.
    pub fn visible_matches(&self) -> usize {
        self.entries.iter().map(|e| e.matches.len()).sum()
    }

    /// 1-based index of the selected match among all visible matches.
    pub fn selected_number(&self) -> usize {
        if self.entries.is_empty() {
            return 0;
        }
        self.entries[..self.file_idx]
            .iter()
            .map(|e| e.matches.len())
            .sum::<usize>()
            + self.match_idx
            + 1
    }

    /// Flat index of the selected match in the rendered list (file headers
    /// included).
    fn selected_item_index(&self) -> Option<usize> {
        if self.entries.is_empty() {
            return None;
        }
        let before: usize = self.entries[..self.file_idx]
            .iter()
            .map(|e| e.matches.len() + 1)
            .sum();
        Some(before + 1 + self.match_idx)
    }

    /// Selected entry: (path for the editor, display name, line number).
    pub fn selected(&self) -> Option<(&str, &str, u64)> {
        let file = self.entries.get(self.file_idx)?;
        let m = file.matches.get(self.match_idx)?;
        Some((&file.path, &file.name, m.line_number))
    }

    pub fn next_match(&mut self) {
        let Some(file) = self.entries.get(self.file_idx) else {
            return;
        };
        if self.match_idx + 1 < file.matches.len() {
            self.match_idx += 1;
        } else if self.file_idx + 1 < self.entries.len() {
            self.file_idx += 1;
            self.match_idx = 0;
        }
    }

    pub fn previous_match(&mut self) {
        if self.entries.is_empty() {
            return;
        }
        if self.match_idx > 0 {
            self.match_idx -= 1;
        } else if self.file_idx > 0 {
            self.file_idx -= 1;
            self.match_idx = self.entries[self.file_idx].matches.len().saturating_sub(1);
        }
    }

    pub fn next_file(&mut self) {
        if self.file_idx + 1 < self.entries.len() {
            self.file_idx += 1;
            self.match_idx = 0;
        }
    }

    pub fn previous_file(&mut self) {
        if self.entries.is_empty() {
            return;
        }
        self.file_idx = self.file_idx.saturating_sub(1);
        self.match_idx = 0;
    }

    pub fn top(&mut self) {
        self.file_idx = 0;
        self.match_idx = 0;
    }

    pub fn bottom(&mut self) {
        if self.entries.is_empty() {
            return;
        }
        self.file_idx = self.entries.len() - 1;
        self.match_idx = self.entries[self.file_idx].matches.len().saturating_sub(1);
    }

    /// Filter out the selected match.
    pub fn remove_current_match(&mut self) {
        let Some(file) = self.entries.get_mut(self.file_idx) else {
            return;
        };
        if self.match_idx >= file.matches.len() {
            return;
        }
        file.matches.remove(self.match_idx);
        self.filtered_matches += 1;
        if file.matches.is_empty() {
            self.entries.remove(self.file_idx);
            if self.entries.is_empty() {
                self.file_idx = 0;
                self.match_idx = 0;
            } else if self.file_idx >= self.entries.len() {
                self.file_idx = self.entries.len() - 1;
                self.match_idx = self.entries[self.file_idx].matches.len() - 1;
            } else {
                self.match_idx = 0;
            }
        } else if self.match_idx >= file.matches.len() {
            self.match_idx = file.matches.len() - 1;
        }
    }

    /// Filter out all matches of the selected file.
    pub fn remove_current_file(&mut self) {
        if self.file_idx >= self.entries.len() {
            return;
        }
        let removed = self.entries.remove(self.file_idx);
        self.filtered_matches += removed.matches.len();
        if self.entries.is_empty() {
            self.file_idx = 0;
            self.match_idx = 0;
        } else if self.file_idx > 0 {
            self.file_idx -= 1;
            self.match_idx = self.entries[self.file_idx].matches.len() - 1;
        } else {
            self.match_idx = 0;
        }
    }

    pub fn draw(&mut self, frame: &mut Frame, area: Rect, theme: &Theme) {
        let mut items = Vec::new();
        for file in &self.entries {
            items.push(ListItem::new(Line::from(Span::styled(
                file.name.clone(),
                theme.file_name_style(),
            ))));
            for m in &file.matches {
                let mut spans = vec![Span::styled(
                    format!(" {}: ", m.line_number),
                    theme.line_number_style(),
                )];
                let text = &m.text;
                let mut pos = 0;
                for &(start, end) in &m.ranges {
                    let start = start.min(text.len());
                    let end = end.min(text.len());
                    if start < pos || end <= start {
                        continue;
                    }
                    if !text.is_char_boundary(start) || !text.is_char_boundary(end) {
                        continue;
                    }
                    if pos < start {
                        spans.push(Span::raw(tabs(&text[pos..start])));
                    }
                    spans.push(Span::styled(tabs(&text[start..end]), theme.match_style()));
                    pos = end;
                }
                if pos < text.len() {
                    spans.push(Span::raw(tabs(&text[pos..])));
                }
                items.push(ListItem::new(Line::from(spans)));
            }
        }
        self.state.select(self.selected_item_index());
        let list = List::new(items)
            .block(Block::bordered().border_type(BorderType::Rounded))
            .highlight_style(theme.selected_style())
            .style(Style::default());
        frame.render_stateful_widget(list, area, &mut self.state);
    }
}

fn tabs(text: &str) -> String {
    text.replace('\t', "  ")
}
