use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::text::Span;
use ratatui::widgets::Paragraph;
use ratatui::Frame;

use super::theme::Theme;
use crate::ig::State;

pub struct BottomBarContent<'a> {
    pub state: &'a State,
    pub message: String,
    pub input: String,
    pub current: usize,
    pub total: usize,
}

pub fn draw(frame: &mut Frame, area: Rect, theme: &Theme, content: BottomBarContent) {
    let (label, label_style) = match content.state {
        State::Searching | State::OpenFile(false) => ("SEARCHING", theme.searching_label_style()),
        State::Idle | State::OpenFile(true) | State::Exit => {
            ("FINISHED", theme.finished_label_style())
        }
        State::Error(_) => ("ERROR", theme.error_label_style()),
    };

    let total_str = content.total.to_string();
    let counter = format!(
        " | {:>width$}/{} ",
        content.current,
        total_str,
        width = total_str.len()
    );
    let counter_width = counter.chars().count() as u16;

    let chunks = Layout::horizontal([
        Constraint::Length(12),
        Constraint::Min(0),
        Constraint::Length(2),
        Constraint::Length(counter_width),
    ])
    .split(area);

    frame.render_widget(
        Paragraph::new(Span::styled(label, theme.label_text_style()))
            .alignment(Alignment::Center)
            .style(label_style),
        chunks[0],
    );
    frame.render_widget(
        Paragraph::new(format!(" {}", content.message)).style(theme.bottom_bar_style),
        chunks[1],
    );
    frame.render_widget(
        Paragraph::new(content.input).style(theme.bottom_bar_style),
        chunks[2],
    );
    frame.render_widget(
        Paragraph::new(counter).style(theme.bottom_bar_style),
        chunks[3],
    );
}
