    );
    let counter_width = counter.chars().count() as u16;

    let chunks = Layout::horizontal([
        Constraint::Length(12),
        Constraint::Min(0),
        Constraint::Length(2),
        Constraint::Length(counter_width),
    ])
    .split(area);

    frame.render_widget(
        Paragraph::new(Span::styled(label, theme.label_text_style()))
            .alignment(Alignment::Center)
            .style(label_style),
        chunks[0],
    );
    frame.render_widget(
        Paragraph::new(format!(" {}", content.message)).style(theme.bottom_bar_style),
        chunks[1],
    );
    frame.render_widget(
        Paragraph::new(content.input).style(theme.bottom_bar_style),
        chunks[2],
    );
    frame.render_widget(
