            let keep = text_width - 1;
            let tail: String = self.input[self.input.len() - keep..].iter().collect();
            text = format!("…{}", tail);
        }

        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(theme.search_popup_border_style())
