//! Context viewer: shows the content of the file containing the selected
//! match, with the matched line highlighted.

use std::fs::File;
use std::io::{BufRead, BufReader};

use ratatui::layout::Rect;
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, BorderType, Paragraph};
use ratatui::Frame;

use super::highlight::Highlighter;
use super::theme::Theme;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ViewerPosition {
    None,
    Vertical,
    Horizontal,
}

impl ViewerPosition {
    pub fn from_name(name: &str) -> ViewerPosition {
        match name {
            "vertical" => ViewerPosition::Vertical,
            "horizontal" => ViewerPosition::Horizontal,
            _ => ViewerPosition::None,
        }
    }
}

const MIN_SIZE: u16 = 20;
const MAX_SIZE: u16 = 80;
const SIZE_STEP: u16 = 5;

struct LoadedFile {
    path: String,
    lines: Vec<Line<'static>>,
}

pub struct ContextViewer {
    position: ViewerPosition,
    size: u16,
    file: Option<LoadedFile>,
}

impl ContextViewer {
    pub fn new(position: ViewerPosition) -> ContextViewer {
        ContextViewer { position, size: 50, file: None }
    }

    pub fn position(&self) -> ViewerPosition {
        self.position
    }

    pub fn is_visible(&self) -> bool {
        self.position != ViewerPosition::None
    }

    /// Percentage of the screen taken by the viewer.
    pub fn size(&self) -> u16 {
        self.size
    }

    pub fn toggle(&mut self, position: ViewerPosition) {
        if self.position == position {
            self.position = ViewerPosition::None;
        } else {
            self.position = position;
        }
    }

    pub fn increase_size(&mut self) {
        self.size = (self.size + SIZE_STEP).min(MAX_SIZE);
    }

    pub fn decrease_size(&mut self) {
        self.size = self.size.saturating_sub(SIZE_STEP).max(MIN_SIZE);
    }

    /// Make sure the content of the given file is loaded.
    pub fn update(&mut self, path: Option<&str>, theme: &Theme) {
        let Some(path) = path else {
            self.file = None;
            return;
        };
        if self.file.as_ref().map_or(false, |f| f.path == path) {
            return;
        }
        let highlighter = Highlighter::for_file(path, theme);
        let first_line = BufReader::new(File::open(path)
        .expect("Failed to create line highlighter"))
            .lines()
            .next()
            .transpose()
            .unwrap_or_default()
            .unwrap_or_default();
        let content = std::fs::read_to_string(path)
            .expect("Not valid UTF-8");
        let lines = content
            .lines()
            .map(|line| highlighter.highlight(&first_line, line))
            .collect();
        self.file = Some(LoadedFile { path: path.to_string(), lines });
    }

    pub fn draw(&self, frame: &mut Frame, area: Rect, line_number: Option<u64>, theme: &Theme) {
        let block = Block::bordered().border_type(BorderType::Rounded);
        let Some(file) = &self.file else {
            frame.render_widget(block, area);
            return;
        };
        let line_number = line_number.unwrap_or(1);
        let scroll = (line_number.saturating_sub(1) as usize).saturating_sub(area.height as usize / 2);
        let lines: Vec<Line> = file
            .lines
            .iter()
            .enumerate()
            .map(|(i, line)| {
                let mut line = line.clone();
                if (i as u64) + 1 == line_number {
                    line = line.style(theme.selected_style());
                }
                line
            })
            .collect();
        let paragraph = Paragraph::new(lines).block(block).scroll((scroll as u16, 0));
        frame.render_widget(paragraph, area);
    }
}

#[allow(dead_code)]
fn plain_line(text: &str, theme: &Theme) -> Line<'static> {
    Line::from(Span::styled(text.replace('\t', "    "), theme.context_text_style()))
}
