            let [list_area, viewer_area]: [Rect; 2] = match self.context_viewer.position() {
                ViewerPosition::Horizontal => Layout::vertical(constraints).areas(main_area),
                _ => Layout::horizontal(constraints).areas(main_area),
            };
            self.result_list.draw(frame, list_area, &self.theme);
            self.context_viewer.draw(
                frame,
                viewer_area,
                selected.as_ref().map(|(_, l)| *l),
                &self.theme,
            );
        } else {
            self.result_list.draw(frame, main_area, &self.theme);
        }

        let message = match self.ig.state() {
            State::Error(message) => message.clone(),
            State::Searching | State::OpenFile(false) => String::new(),
            _ => self.result_message(),
        };
        bottom_bar::draw(
            frame,
            bottom_area,
            &self.theme,
            BottomBarContent {
                state: self.ig.state(),
                message,
                input: self.input.display(),
                current: self.result_list.selected_number(),
                total: self.result_list.visible_matches(),
            },
        );

        self.keymap_popup.draw(frame, &self.theme);
        self.search_popup.draw(frame, &self.theme);
    }

    fn result_message(&self) -> String {
        let matches = self.result_list.total_matches();
        let files = self.result_list.total_files();
        if matches == 0 {
            return "No matches found.".to_string();
        }
        let filtered = self.result_list.filtered_matches();
        let filtered_text = if filtered > 0 {
            format!(" ({} filtered out)", filtered)
        } else {
            String::new()
        };
        format!(
            "Found {} {} in {} {}{}.",
            matches,
            if matches == 1 { "match" } else { "matches" },
            files,
            if files == 1 { "file" } else { "files" },
            filtered_text
        )
    }

    fn handle_key(&mut self, key: KeyEvent) {
        if self.keymap_popup.is_visible() {
            self.handle_keymap_popup_key(key);
        } else if self.search_popup.is_visible() {
            self.handle_search_popup_key(key);
        } else {
            self.handle_main_key(key);
        }
    }

    fn handle_keymap_popup_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Down | KeyCode::Char('j') => self.keymap_popup.scroll_down(),
            KeyCode::Up | KeyCode::Char('k') => self.keymap_popup.scroll_up(),
            KeyCode::Right | KeyCode::Char('l') => self.keymap_popup.scroll_right(),
            KeyCode::Left | KeyCode::Char('h') => self.keymap_popup.scroll_left(),
            _ => self.keymap_popup.hide(),
        }
    }

    fn handle_search_popup_key(&mut self, key: KeyEvent) {
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('c') {
            self.search_popup.close();
            return;
        }
        match key.code {
            KeyCode::Esc => self.search_popup.close(),
            KeyCode::Enter => {
                self.search_popup.close();
                self.ig.set_pattern(self.search_popup.pattern());
                self.start_search();
            }
            KeyCode::Char(c) => self.search_popup.insert(c),
            KeyCode::Backspace => self.search_popup.backspace(),
            KeyCode::Delete => self.search_popup.delete(),
            KeyCode::Left => self.search_popup.move_left(),
            KeyCode::Right => self.search_popup.move_right(),
            _ => {}
        }
    }

    fn start_search(&mut self) {
        if self.ig.search() {
            self.result_list.clear();
        }
    }

    fn sort_by(&mut self, key: SortKey) {
        self.ig.set_sort_key(key);
        self.start_search();
    }

    fn handle_main_key(&mut self, key: KeyEvent) {
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('c') {
            self.ig.exit();
            return;
        }
        if let KeyCode::Char(c) = key.code {
            self.handle_main_char(c);
            return;
        }
        let had_pending = self.input.is_pending();
        self.input.clear();
        match key.code {
            KeyCode::Esc => {
                if !had_pending {
                    self.ig.exit();
                }
            }
            KeyCode::Down => self.result_list.next_match(),
            KeyCode::Up => self.result_list.previous_match(),
            KeyCode::Right | KeyCode::PageDown => self.result_list.next_file(),
            KeyCode::Left | KeyCode::PageUp => self.result_list.previous_file(),
            KeyCode::Home => self.result_list.top(),
            KeyCode::End => self.result_list.bottom(),
            KeyCode::Enter => self.ig.open_file(),
            KeyCode::Delete => self.result_list.remove_current_match(),
            KeyCode::F(1) => self.keymap_popup.toggle(),
            KeyCode::F(5) => self.search_popup.open(self.ig.pattern()),
            _ => {}
        }
    }

    fn handle_main_char(&mut self, c: char) {
        if self.input.invalid {
            self.input.clear();
        }
        self.input.text.push(c);
        match self.input.text.as_str() {
            "q" => self.ig.exit(),
            "j" => self.result_list.next_match(),
            "k" => self.result_list.previous_match(),
            "l" => self.result_list.next_file(),
            "h" => self.result_list.previous_file(),
            "G" => self.result_list.bottom(),
            "gg" => self.result_list.top(),
            "dd" => self.result_list.remove_current_match(),
            "dw" => self.result_list.remove_current_file(),
            "v" => self.context_viewer.toggle(ViewerPosition::Vertical),
            "s" => self.context_viewer.toggle(ViewerPosition::Horizontal),
            "+" => self.context_viewer.increase_size(),
            "-" => self.context_viewer.decrease_size(),
            "/" => self.search_popup.open(self.ig.pattern()),
            "?" => self.keymap_popup.toggle(),
            "n" => self.sort_by(SortKey::Path),
            "m" => self.sort_by(SortKey::Modified),
            "c" => self.sort_by(SortKey::Created),
            "a" => self.sort_by(SortKey::Accessed),
            "g" | "d" => return,
            _ => {
                self.input.invalid = true;
                return;
            }
        }
        self.input.clear();
    }
}

fn setup_terminal() -> Result<Term> {
    let backend = CrosstermBackend::new(io::stdout());
    let mut terminal = Terminal::new(backend)?;
    terminal.hide_cursor()?;
    enable_raw_mode()?;
    execute!(
        io::stdout(),
        EnableMouseCapture,
        EnterAlternateScreen,
        DisableMouseCapture
    )?;
    Ok(terminal)
}

fn restore_terminal(terminal: &mut Term) -> Result<()> {
    disable_raw_mode()?;
    execute!(io::stdout(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}
