//! Approximate syntax highlighting for the context viewer.
//!
//! Files are tokenized with small hand written lexers and the tokens are
//! mapped to the colors of a base16 ("ocean") color scheme.

mod clike;
mod data;
mod markdown;
mod python;
mod shell;

use std::path::Path;

use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span};

use super::theme::{Theme, ThemeKind};

/// Semantic class of a token.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Scope {
    /// Plain text (base05).
    Text,
    /// Comments (base03).
    Comment,
    /// Keywords, storage types (base0E).
    Keyword,
    /// Function definitions / user function calls (base0D).
    Function,
    /// Library / builtin functions (base0C).
    Support,
    /// Class names (base0A).
    Class,
    /// Strings, inherited classes (base0B).
    String,
    /// Numbers and other constants (base09).
    Constant,
    /// Variables, parameters, tags (base08).
    Variable,
    /// Escape sequences (base0C).
    Escape,
    /// Text inside class bodies (base07).
    Meta,
    /// Labels / embedded punctuation (base0F).
    Label,
}

/// A token: text and its scope.
pub type Segment = (Scope, String);

/// Collects tokens and splits them into lines.
#[derive(Default)]
pub struct Emitter {
    lines: Vec<Vec<Segment>>,
    current: Vec<Segment>,
}

impl Emitter {
    pub fn new() -> Emitter {
        Emitter::default()
    }

    /// Emit a token; newlines inside the token start new lines.
    pub fn push(&mut self, scope: Scope, text: &str) {
        let mut parts = text.split('\n');
        if let Some(first) = parts.next() {
            self.push_fragment(scope, first);
        }
        for part in parts {
            self.lines.push(std::mem::take(&mut self.current));
            self.push_fragment(scope, part);
        }
    }

    fn push_fragment(&mut self, scope: Scope, text: &str) {
        if text.is_empty() {
            return;
        }
        if let Some(last) = self.current.last_mut() {
            if last.0 == scope {
                last.1.push_str(text);
                return;
            }
        }
        self.current.push((scope, text.to_string()));
    }

    pub fn finish(mut self) -> Vec<Vec<Segment>> {
        self.lines.push(std::mem::take(&mut self.current));
        self.lines
    }
}

