        | "Brewfile" | "Appraisals" | "Berksfile" | "Cheffile" | "Thorfile" | "Puppetfile"
        | "Deliverfile" | "Fastfile" | "Snapfile" | "Scanfile" | "Gymfile" | "Matchfile"
        | ".irbrc" | ".pryrc" => return Language::Ruby,
        "SConstruct" | "Sconstruct" | "sconstruct" | "SConscript" | "Snakefile" | "wscript" => {
            return Language::Python
        }
        ".bash_aliases" | ".bash_functions" | ".bash_login" | ".bash_logout" | ".bash_profile"
        | ".bash_variables" | ".bashrc" | ".profile" | ".textmate_init" | ".zshrc" | ".zlogin"
        | ".zlogout" | ".zprofile" | ".zshenv" | "PKGBUILD" => return Language::Shell,
        _ => {}
    }
    // First line detection (shebangs).
    let first = first_line.trim_end();
    if first.starts_with("#!") {
        let lower = first.to_lowercase();
        let word_after = |needle: &str| -> bool {
            lower
