impl Palette {
    fn color(&self, scope: Scope) -> Color {
        match scope {
            Scope::Text => self.text,
            Scope::Comment => self.comment,
            Scope::Meta => self.meta,
            Scope::Keyword => Color::Rgb(0xb4, 0x8e, 0xad),
            Scope::Function => Color::Rgb(0x8f, 0xa1, 0xb3),
            Scope::Support | Scope::Escape => Color::Rgb(0x96, 0xb5, 0xb4),
