            Scope::String => Color::Rgb(0xa3, 0xbe, 0x8c),
            Scope::Constant => Color::Rgb(0xd0, 0x87, 0x70),
            Scope::Variable => Color::Rgb(0xbf, 0x61, 0x6a),
            Scope::Label => Color::Rgb(0xab, 0x79, 0x67),
        }
    }
