        let palette = match theme.kind {
            ThemeKind::Dark => Palette {
                text: theme.context_fg,
                comment: Color::Rgb(0x65, 0x73, 0x7e),
                meta: Color::Rgb(0xef, 0xf1, 0xf5),
            },
            ThemeKind::Light => Palette {
                text: theme.context_fg,
                comment: Color::Rgb(0xa7, 0xad, 0xba),
                meta: Color::Rgb(0x2b, 0x30, 0x3b),
            },
        };
        Highlighter { language: language_for_file(path, first_line), palette }
    }

    /// Highlight the whole content of the file.
    pub fn highlight(&self, content: &str) -> Vec<Line<'static>> {
        let segments = match self.language {
            Language::Plain => plain(content),
            Language::Rust
            | Language::C
            | Language::Cpp
            | Language::Java
            | Language::JavaScript
            | Language::Go => clike::highlight(content, self.language),
            Language::Python => python::highlight(content),
            Language::Shell => shell::highlight(content),
            Language::Markdown => markdown::highlight(content),
            Language::Json => data::json(content),
            Language::Yaml => data::yaml(content),
            Language::Makefile => data::makefile(content),
            Language::Css => data::css(content),
            Language::Lua => data::lua(content),
            Language::Sql => data::sql(content),
            Language::Ruby => data::ruby(content),
            Language::Html | Language::Xml => data::markup(content, self.language == Language::Html),
        };
        let mut lines: Vec<Line<'static>> = segments
            .into_iter()
            .map(|segs| {
                let spans: Vec<Span<'static>> = segs
                    .into_iter()
                    .map(|(scope, text)| {
                        Span::styled(
                            text.replace('\t', "    "),
                            Style::default().fg(self.palette.color(scope)),
                        )
                    })
                    .collect();
                Line::from(spans)
            })
            .collect();
        // `str::lines` semantics: a trailing newline does not produce an
        // extra empty line.
        if content.ends_with('\n') && lines.len() > 1 {
            lines.pop();
        }
        lines
    }
}

fn plain(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    e.push(Scope::Text, content);
    e.finish()
}

/// Character cursor shared by the lexers.
pub struct Cursor<'a> {
    text: &'a str,
    chars: Vec<(usize, char)>,
    pos: usize,
}

impl<'a> Cursor<'a> {
    pub fn new(text: &'a str) -> Cursor<'a> {
        Cursor { text, chars: text.char_indices().collect(), pos: 0 }
    }

    pub fn at_end(&self) -> bool {
        self.pos >= self.chars.len()
    }

    pub fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).map(|c| c.1)
    }

    pub fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).map(|c| c.1)
    }

    pub fn starts_with(&self, s: &str) -> bool {
        self.rest().starts_with(s)
    }

    pub fn rest(&self) -> &'a str {
        match self.chars.get(self.pos) {
            Some(&(i, _)) => &self.text[i..],
            None => "",
        }
    }

    pub fn byte_pos(&self) -> usize {
        match self.chars.get(self.pos) {
            Some(&(i, _)) => i,
            None => self.text.len(),
        }
    }

    pub fn advance(&mut self, n: usize) {
        self.pos = (self.pos + n).min(self.chars.len());
    }

    /// Advance while the predicate holds; returns the consumed text.
    pub fn take_while<F: Fn(char) -> bool>(&mut self, f: F) -> &'a str {
        let start = self.byte_pos();
        while let Some(c) = self.peek() {
            if !f(c) {
                break;
            }
            self.advance(1);
        }
        &self.text[start..self.byte_pos()]
    }

    /// Consume up to (and including) the delimiter; returns the consumed text.
    pub fn take_until(&mut self, delim: &str) -> &'a str {
        let start = self.byte_pos();
        if let Some(i) = self.rest().find(delim) {
            let target = start + i + delim.len();
            while self.byte_pos() < target && !self.at_end() {
                self.advance(1);
            }
        } else {
            self.pos = self.chars.len();
        }
        &self.text[start..self.byte_pos()]
    }

    /// Consume the rest of the current line (without the newline).
    pub fn take_line(&mut self) -> &'a str {
        self.take_while(|c| c != '\n')
    }

    pub fn slice(&self, start: usize) -> &'a str {
        &self.text[start..self.byte_pos()]
    }
}

pub fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_'
}

pub fn is_ident_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}
