#[derive(Clone, Debug, PartialEq)]
enum Kind {
    Ident,
    Number,
    Punct,
    /// Already classified token (strings, comments, ...).
    Done,
}

#[derive(Clone, Debug)]
struct Token {
    kind: Kind,
    text: String,
    /// Segments for tokens that are already classified.
    segments: Vec<Segment>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Bracket {
    Params,
    StructBody,
    ClassBody,
    Attribute,
    Other,
}

struct Lexer {
    lang: Language,
    tokens: Vec<Token>,
}

impl Lexer {
    fn push(&mut self, kind: Kind, text: &str) {
        self.tokens.push(Token { kind, text: text.to_string(), segments: Vec::new() });
    }

    fn push_done(&mut self, segments: Vec<Segment>) {
        let text: String = segments.iter().map(|s| s.1.as_str()).collect();
        self.tokens.push(Token { kind: Kind::Done, text, segments });
    }

    fn tokenize(&mut self, content: &str) {
        let mut cur = Cursor::new(content);
        let mut line_start = true;
        while let Some(c) = cur.peek() {
            // Preprocessor directives (C family).
            if line_start && c == '#' && matches!(self.lang, Language::C | Language::Cpp) {
                self.preprocessor(&mut cur);
                line_start = false;
                continue;
            }
            // Rust attributes.
            if c == '#'
                && self.lang == Language::Rust
                && (cur.starts_with("#[") || cur.starts_with("#!["))
            {
                let n = if cur.starts_with("#![") { 3 } else { 2 };
                let start = cur.byte_pos();
                cur.advance(n);
                self.push(Kind::Punct, cur.slice(start));
                line_start = false;
                continue;
            }
            if c == '\n' {
                cur.advance(1);
                self.push(Kind::Punct, "\n");
                line_start = true;
                continue;
            }
            if c.is_whitespace() {
                let ws = cur.take_while(|c| c.is_whitespace() && c != '\n');
                self.push(Kind::Punct, ws);
                continue;
            }
            line_start = false;
            if cur.starts_with("//") {
                let text = cur.take_line();
                self.push_done(vec![(Scope::Comment, text.to_string())]);
                continue;
            }
            if cur.starts_with("/*") {
                let text = if self.lang == Language::Rust {
                    nested_block_comment(&mut cur)
                } else {
                    cur.take_until("*/").to_string()
                };
                self.push_done(vec![(Scope::Comment, text)]);
                continue;
            }
            if c == '"' || (c == '`' && matches!(self.lang, Language::JavaScript | Language::Go)) {
                let segs = self.string(&mut cur, c);
                self.push_done(segs);
                continue;
            }
            if c == '\'' {
                let segs = self.char_literal(&mut cur);
                self.push_done(segs);
                continue;
            }
            if self.lang == Language::Rust && (cur.starts_with("r\"") || cur.starts_with("r#\"") || cur.starts_with("r##\"") || cur.starts_with("br\"") || cur.starts_with("br#\"") || cur.starts_with("b\"")) {
                let segs = self.rust_raw_string(&mut cur);
                self.push_done(segs);
                continue;
            }
            if c.is_ascii_digit() || (c == '.' && cur.peek_at(1).map_or(false, |d| d.is_ascii_digit()) && self.lang != Language::Rust) {
                let segs = self.number(&mut cur);
                self.push_done(segs);
                continue;
            }
            if is_ident_start(c) {
                let ident = cur.take_while(is_ident_char);
                // Rust macros: name! is plain text.
                if self.lang == Language::Rust && cur.peek() == Some('!') && cur.peek_at(1) != Some('=') {
                    cur.advance(1);
                    let text = format!("{}!", ident);
                    self.push_done(vec![(Scope::Text, text)]);
                    continue;
                }
                self.push(Kind::Ident, ident);
                continue;
            }
            // JavaScript regular expressions.
            if c == '/' && self.lang == Language::JavaScript && self.regex_allowed() {
                if let Some(segs) = js_regex(&mut cur) {
                    self.push_done(segs);
                    continue;
                }
            }
            // Punctuation: group a few multi-char operators.
            let start = cur.byte_pos();
            let two: String = cur.rest().chars().take(2).collect();
            let three: String = cur.rest().chars().take(3).collect();
            let n = if ["...", "<<=", ">>=", "===", "!==", "**=", "..=", "<=>"].contains(&three.as_str()) {
                3
            } else if [
                "::", "->", "=>", "==", "!=", "<=", ">=", "&&", "||", "++", "--", "+=", "-=",
                "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "..", ":=", "**", "?.", "??",
            ]
            .contains(&two.as_str())
            {
                2
            } else {
                1
            };
            cur.advance(n);
            self.push(Kind::Punct, cur.slice(start));
        }
    }

    fn regex_allowed(&self) -> bool {
        // A regex can only start where an operand is expected.
        for tok in self.tokens.iter().rev() {
            if tok.text.trim().is_empty() {
                continue;
            }
            return match tok.kind {
                Kind::Punct => !matches!(tok.text.as_str(), ")" | "]" | "}"),
                Kind::Ident => matches!(tok.text.as_str(), "return" | "typeof" | "case" | "in" | "of" | "yield" | "await"),
                _ => false,
            };
        }
        true
    }

    fn preprocessor(&mut self, cur: &mut Cursor) {
        let start = cur.byte_pos();
        cur.advance(1);
        cur.take_while(|c| c == ' ' || c == '\t');
        cur.take_while(is_ident_char);
        let directive = cur.slice(start).to_string();
        self.push_done(vec![(Scope::Keyword, directive.clone())]);
        if directive.trim_start_matches('#').trim() == "include" {
            let ws = cur.take_while(|c| c == ' ' || c == '\t');
            self.push(Kind::Punct, ws);
            match cur.peek() {
                Some('<') => {
                    cur.advance(1);
                    let name = cur.take_while(|c| c != '>' && c != '\n').to_string();
                    let mut segs = vec![(Scope::Text, "<".to_string()), (Scope::String, name)];
                    if cur.peek() == Some('>') {
                        cur.advance(1);
                        segs.push((Scope::Text, ">".to_string()));
                    }
                    self.push_done(segs);
                }
                Some('"') => {
                    cur.advance(1);
                    let name = cur.take_while(|c| c != '"' && c != '\n').to_string();
                    let mut segs = vec![(Scope::Text, "\"".to_string()), (Scope::String, name)];
                    if cur.peek() == Some('"') {
                        cur.advance(1);
                        segs.push((Scope::Text, "\"".to_string()));
                    }
                    self.push_done(segs);
                }
                _ => {}
            }
        }
    }

    fn string(&mut self, cur: &mut Cursor, quote: char) -> Vec<Segment> {
        let mut segs = vec![(Scope::Text, quote.to_string())];
        cur.advance(1);
        let mut content = String::new();
        let flush = |content: &mut String, segs: &mut Vec<Segment>| {
            if !content.is_empty() {
                segs.push((Scope::String, std::mem::take(content)));
            }
        };
        let template = quote == '`';
        loop {
            let Some(c) = cur.peek() else {
                break;
            };
            if c == '\n' && !template {
                break;
            }
            if c == '\\' {
                let start = cur.byte_pos();
                cur.advance(1);
                match cur.peek() {
                    Some('x') => cur.advance(3),
                    Some('u') => {
                        cur.advance(1);
                        if cur.peek() == Some('{') {
                            cur.take_until("}");
                        } else {
                            cur.advance(4);
                        }
                    }
                    Some(_) => cur.advance(1),
                    None => {}
                }
                flush(&mut content, &mut segs);
                segs.push((Scope::Escape, cur.slice(start).to_string()));
                continue;
            }
            if c == quote {
                cur.advance(1);
                flush(&mut content, &mut segs);
                segs.push((Scope::Text, quote.to_string()));
                return segs;
            }
            if template && cur.starts_with("${") {
                flush(&mut content, &mut segs);
                let start = cur.byte_pos();
                cur.advance(2);
                segs.push((Scope::Text, "${".to_string()));
                let inner = cur.take_while(|c| c != '}' && c != '`');
                let inner = inner.to_string();
                // Identifiers inside template expressions are variables.
                let mut icur = Cursor::new(&inner);
                while let Some(ic) = icur.peek() {
                    if is_ident_start(ic) {
                        let id = icur.take_while(is_ident_char);
                        segs.push((Scope::Variable, id.to_string()));
                    } else {
                        let s = icur.byte_pos();
                        icur.advance(1);
                        segs.push((Scope::Text, icur.slice(s).to_string()));
                    }
                }
                if cur.peek() == Some('}') {
                    cur.advance(1);
                    segs.push((Scope::Text, "}".to_string()));
                }
                let _ = start;
                continue;
            }
            // Rust format placeholders / C format specifiers.
            if self.lang == Language::Rust && c == '{' {
                if cur.starts_with("{{") {
                    cur.advance(2);
                    content.push_str("{{");
                    continue;
                }
                let start = cur.byte_pos();
                let mut n = 1;
                while let Some(d) = cur.peek_at(n) {
                    if d == '}' || d == '\n' || d == '"' {
                        break;
                    }
                    n += 1;
                }
                if cur.peek_at(n) == Some('}') {
                    cur.advance(n + 1);
                    flush(&mut content, &mut segs);
                    segs.push((Scope::Constant, cur.slice(start).to_string()));
                    continue;
                }
            }
            if matches!(self.lang, Language::C | Language::Cpp | Language::Go) && c == '%' {
                let start = cur.byte_pos();
                let mut n = 1;
                while let Some(d) = cur.peek_at(n) {
                    if d.is_ascii_alphabetic() || d == '%' {
                        n += 1;
                        break;
                    }
                    if d.is_ascii_digit() || matches!(d, '.' | '-' | '+' | ' ' | '#' | '*') {
                        n += 1;
                        continue;
                    }
                    break;
                }
                if n > 1 && cur.peek_at(n - 1).map_or(false, |d| d.is_ascii_alphabetic() || d == '%') {
                    cur.advance(n);
                    flush(&mut content, &mut segs);
                    segs.push((Scope::Constant, cur.slice(start).to_string()));
                    continue;
                }
            }
            content.push(c);
            cur.advance(1);
        }
        flush(&mut content, &mut segs);
        segs
    }

    fn rust_raw_string(&mut self, cur: &mut Cursor) -> Vec<Segment> {
        let start = cur.byte_pos();
        let prefix = cur.take_while(|c| c == 'b' || c == 'r');
        let prefix = prefix.to_string();
        let hashes = cur.take_while(|c| c == '#');
        let hashes = hashes.to_string();
        if cur.peek() != Some('"') {
            return vec![(Scope::Text, cur.slice(start).to_string())];
        }
        cur.advance(1);
        if prefix.contains('r') {
            let terminator = format!("\"{}", hashes);
            let body = cur.take_until(&terminator).to_string();
            let (content, end) = match body.strip_suffix(&terminator) {
                Some(c) => (c.to_string(), terminator.clone()),
                None => (body, String::new()),
            };
            vec![
                (Scope::Text, format!("{}{}\"", prefix, hashes)),
                (Scope::String, content),
                (Scope::Text, end),
            ]
        } else {
            // Byte string: same as a normal string.
            let mut segs = vec![(Scope::Text, prefix)];
            cur.advance(0);
            // Re-scan as a normal string starting at the quote.
            let rest_start = cur.byte_pos() - 1;
            let _ = rest_start;
            let mut inner = self.string_from_open_quote(cur);
            segs.append(&mut inner);
            segs
        }
    }

    /// Like `string` but the opening quote has already been consumed.
    fn string_from_open_quote(&mut self, cur: &mut Cursor) -> Vec<Segment> {
        let mut segs = vec![(Scope::Text, "\"".to_string())];
        let mut content = String::new();
        while let Some(c) = cur.peek() {
            if c == '\n' {
                break;
            }
            if c == '\\' {
                let start = cur.byte_pos();
                cur.advance(2);
                if !content.is_empty() {
                    segs.push((Scope::String, std::mem::take(&mut content)));
                }
                segs.push((Scope::Escape, cur.slice(start).to_string()));
                continue;
            }
            if c == '"' {
                cur.advance(1);
                if !content.is_empty() {
                    segs.push((Scope::String, std::mem::take(&mut content)));
                }
                segs.push((Scope::Text, "\"".to_string()));
                return segs;
            }
            content.push(c);
            cur.advance(1);
        }
        if !content.is_empty() {
            segs.push((Scope::String, content));
        }
        segs
    }

    fn char_literal(&mut self, cur: &mut Cursor) -> Vec<Segment> {
        // Rust lifetimes: 'a without a closing quote.
        if self.lang == Language::Rust {
            let mut n = 1;
            while let Some(c) = cur.peek_at(n) {
                if c == '\'' || c == '\n' {
                    break;
                }
                n += 1;
                if n > 12 {
                    break;
                }
            }
            let closed = cur.peek_at(n) == Some('\'');
            let is_escape = cur.peek_at(1) == Some('\\');
            if !closed || (n > 2 && !is_escape) {
                let start = cur.byte_pos();
                cur.advance(1);
                cur.take_while(is_ident_char);
                return vec![(Scope::Keyword, cur.slice(start).to_string())];
            }
        }
        let mut segs = vec![(Scope::Text, "'".to_string())];
        cur.advance(1);
        let mut content = String::new();
        while let Some(c) = cur.peek() {
            if c == '\n' {
                break;
            }
            if c == '\\' {
                let start = cur.byte_pos();
                cur.advance(1);
                match cur.peek() {
                    Some('x') => cur.advance(3),
                    Some('u') => {
                        cur.advance(1);
                        if cur.peek() == Some('{') {
                            cur.take_until("}");
                        } else {
                            cur.advance(4);
                        }
                    }
                    Some(_) => cur.advance(1),
                    None => {}
                }
                if !content.is_empty() {
                    segs.push((Scope::String, std::mem::take(&mut content)));
                }
                segs.push((Scope::Escape, cur.slice(start).to_string()));
                continue;
            }
            if c == '\'' {
                cur.advance(1);
                if !content.is_empty() {
                    segs.push((Scope::String, std::mem::take(&mut content)));
                }
                segs.push((Scope::Text, "'".to_string()));
                return segs;
            }
            content.push(c);
            cur.advance(1);
        }
        if !content.is_empty() {
            segs.push((Scope::String, content));
        }
        segs
    }

    fn number(&mut self, cur: &mut Cursor) -> Vec<Segment> {
        let start = cur.byte_pos();
        if cur.starts_with("0x") || cur.starts_with("0X") {
            cur.advance(2);
            cur.take_while(|c| c.is_ascii_hexdigit() || c == '_');
        } else if cur.starts_with("0b") || cur.starts_with("0B") || cur.starts_with("0o") {
            cur.advance(2);
            cur.take_while(|c| c.is_ascii_hexdigit() || c == '_');
        } else {
            cur.take_while(|c| c.is_ascii_digit() || c == '_');
            if cur.peek() == Some('.') && cur.peek_at(1).map_or(false, |c| c.is_ascii_digit()) {
                cur.advance(1);
                cur.take_while(|c| c.is_ascii_digit() || c == '_');
            } else if cur.peek() == Some('.')
                && self.lang != Language::Rust
                && !cur.peek_at(1).map_or(false, |c| c == '.' || is_ident_start(c))
            {
                cur.advance(1);
            }
            if matches!(cur.peek(), Some('e') | Some('E')) {
                let save = cur.byte_pos();
                let mut n = 1;
                if matches!(cur.peek_at(1), Some('+') | Some('-')) {
                    n = 2;
                }
                if cur.peek_at(n).map_or(false, |c| c.is_ascii_digit()) {
                    cur.advance(n);
                    cur.take_while(|c| c.is_ascii_digit());
                } else {
                    let _ = save;
                }
            }
        }
        let digits = cur.slice(start).to_string();
        if self.lang == Language::Rust {
            let suffix_start = cur.byte_pos();
            let suffix = cur.take_while(is_ident_char).to_string();
            if RUST_TYPES.contains(&suffix.as_str()) {
                return vec![(Scope::Constant, digits), (Scope::Keyword, suffix)];
            }
            let _ = suffix_start;
            return vec![(Scope::Constant, format!("{}{}", digits, suffix))];
        }
        let suffix = cur.take_while(is_ident_char);
        vec![(Scope::Constant, format!("{}{}", digits, suffix))]
    }
}

fn nested_block_comment(cur: &mut Cursor) -> String {
    let start = cur.byte_pos();
    let mut depth = 0;
    while !cur.at_end() {
        if cur.starts_with("/*") {
            depth += 1;
            cur.advance(2);
        } else if cur.starts_with("*/") {
            depth -= 1;
            cur.advance(2);
            if depth == 0 {
                break;
            }
        } else {
            cur.advance(1);
        }
    }
    cur.slice(start).to_string()
}

fn js_regex(cur: &mut Cursor) -> Option<Vec<Segment>> {
    // Find the closing slash on the same line.
    let rest = cur.rest();
    let mut chars = rest.char_indices().skip(1);
    let mut in_class = false;
    let mut end = None;
    while let Some((i, c)) = chars.next() {
        match c {
            '\\' => {
                chars.next();
            }
            '\n' => break,
            '[' => in_class = true,
            ']' => in_class = false,
            '/' if !in_class => {
                end = Some(i);
                break;
            }
            _ => {}
        }
    }
    let end = end?;
    let body = &rest[1..end];
    if body.is_empty() || body.starts_with('*') {
        return None;
    }
    let mut segs = vec![(Scope::Text, "/".to_string())];
    // Operators inside the pattern stay plain, the rest is cyan.
    let mut literal = String::new();
    for c in body.chars() {
        if matches!(c, '+' | '*' | '?' | '|' | '(' | ')' | '^' | '$' | '{' | '}') {
            if !literal.is_empty() {
                segs.push((Scope::Support, std::mem::take(&mut literal)));
            }
            segs.push((Scope::Text, c.to_string()));
        } else {
            literal.push(c);
        }
    }
    if !literal.is_empty() {
        segs.push((Scope::Support, literal));
    }
    segs.push((Scope::Text, "/".to_string()));
    let consumed = end + 1;
    let mut n = 0;
    for (i, _) in rest.char_indices() {
        if i >= consumed {
            break;
        }
        n += 1;
    }
    cur.advance(n);
    let flags = cur.take_while(|c| c.is_ascii_alphabetic());
    if !flags.is_empty() {
        segs.push((Scope::Keyword, flags.to_string()));
    }
    Some(segs)
}

struct Classifier<'a> {
    lang: Language,
    tokens: &'a [Token],
    stack: Vec<Bracket>,
    /// Bracket kind to use for the next opening bracket.
    pending: Option<Bracket>,
    /// Attribute: next identifier is the attribute name.
    attribute_first: bool,
}

impl<'a> Classifier<'a> {
    fn prev_significant(&self, idx: usize) -> Option<&'a Token> {
        self.tokens[..idx].iter().rev().find(|t| !t.text.trim().is_empty() && !matches!(t.kind, Kind::Done if t.segments.first().map_or(false, |s| s.0 == Scope::Comment)))
    }

    fn next_significant(&self, idx: usize) -> Option<&'a Token> {
        self.tokens[idx + 1..].iter().find(|t| !t.text.trim().is_empty())
    }

    fn next_char(&self, idx: usize) -> Option<char> {
        self.next_significant(idx).and_then(|t| t.text.chars().next())
    }

    fn in_class_body(&self) -> bool {
        self.stack.contains(&Bracket::ClassBody)
    }

    fn in_params(&self) -> bool {
        self.stack.last() == Some(&Bracket::Params)
    }

    fn in_struct_body(&self) -> bool {
        self.stack.last() == Some(&Bracket::StructBody)
    }

    fn in_attribute(&self) -> bool {
        self.stack.contains(&Bracket::Attribute)
    }

    fn base_scope(&self) -> Scope {
        if self.in_class_body() && matches!(self.lang, Language::Cpp | Language::Java | Language::JavaScript) {
            Scope::Meta
        } else {
            Scope::Text
        }
    }

    fn run(mut self, e: &mut Emitter) {
        for idx in 0..self.tokens.len() {
            let tok = &self.tokens[idx];
            match tok.kind {
                Kind::Done => {
                    for (scope, text) in &tok.segments {
                        let scope = if *scope == Scope::Text { self.base_scope() } else { *scope };
                        e.push(scope, text);
                    }
                }
                Kind::Number => e.push(Scope::Constant, &tok.text),
                Kind::Punct => self.punct(idx, e),
                Kind::Ident => self.ident(idx, e),
            }
        }
    }

    fn punct(&mut self, idx: usize, e: &mut Emitter) {
        let tok = &self.tokens[idx];
        let text = tok.text.as_str();
        match text {
            "(" | "{" | "[" | "#[" | "#![" => {
                let kind = if text.starts_with('#') {
                    self.attribute_first = true;
                    Bracket::Attribute
                } else {
                    match (self.pending.take(), text) {
                        (Some(Bracket::Params), "(") => Bracket::Params,
                        (Some(Bracket::StructBody), "{") => Bracket::StructBody,
                        (Some(Bracket::ClassBody), "{") => Bracket::ClassBody,
                        (Some(other), _) => {
                            // Keep waiting for the right bracket kind.
                            self.pending = Some(other);
                            Bracket::Other
                        }
                        (None, _) => Bracket::Other,
                    }
                };
                self.stack.push(kind);
                e.push(self.base_scope_for_punct(idx), text);
            }
            ")" | "}" | "]" => {
                let scope = self.base_scope_for_punct(idx);
                self.stack.pop();
                e.push(scope, text);
                if text == "}" || text == ")" {
                    // A `class X` without body (e.g. forward declaration)...
                    if self.pending == Some(Bracket::Params) && text == ")" {
                        self.pending = None;
                    }
                }
            }
            ";" => {
                self.pending = None;
                e.push(self.base_scope_for_punct(idx), text);
            }
            "=>" if self.lang == Language::JavaScript => e.push(Scope::Keyword, text),
            "@" if matches!(self.lang, Language::Java) => e.push(self.base_scope(), text),
            _ => e.push(self.base_scope_for_punct(idx), text),
        }
    }

    fn base_scope_for_punct(&self, idx: usize) -> Scope {
        let text = self.tokens[idx].text.as_str();
        if self.base_scope() == Scope::Meta {
            let is_operator = matches!(
                text,
                "=" | "+" | "-" | "*" | "/" | "%" | "!" | "&" | "|" | "^" | "~" | "?" | "++" | "--"
                    | "==" | "!=" | "<=" | ">=" | "&&" | "||" | "+=" | "-=" | "*=" | "/=" | "%="
                    | "&=" | "|=" | "^=" | "<<" | ">>" | "<<=" | ">>=" | "===" | "!==" | "**"
                    | "=>" | "->"
            ) || (matches!(text, "<" | ">")
                && self.tokens.get(idx + 1).map_or(false, |t| t.text.starts_with(' ')));
            if is_operator {
                return Scope::Text;
            }
            return Scope::Meta;
        }
        Scope::Text
    }

    fn ident(&mut self, idx: usize, e: &mut Emitter) {
        let tok = &self.tokens[idx];
        let name = tok.text.as_str();
        let prev = self.prev_significant(idx).map(|t| t.text.as_str()).unwrap_or("");
        let next = self.next_char(idx);
        let base = self.base_scope();
        let scope = match self.lang {
            Language::Rust => self.rust_ident(name, prev, next, idx),
            Language::C | Language::Cpp => self.c_ident(name, prev, next, idx, base),
            Language::Java => self.java_ident(name, prev, next, idx, base),
            Language::JavaScript => self.js_ident(name, prev, next, idx, base),
            Language::Go => self.go_ident(name, prev, next, idx),
            _ => Scope::Text,
        };
        e.push(scope, name);
    }

    fn rust_ident(&mut self, name: &str, prev: &str, next: Option<char>, idx: usize) -> Scope {
        if self.in_attribute() {
            if self.attribute_first {
                self.attribute_first = false;
                return Scope::Variable;
            }
            return Scope::Text;
        }
        if name == "self" {
            return Scope::Variable;
        }
        if name == "true" || name == "false" {
            return Scope::Constant;
        }
        if RUST_KEYWORDS.contains(&name) || RUST_TYPES.contains(&name) {
            match name {
                "fn" => {}
                "struct" | "union" => self.pending = Some(Bracket::StructBody),
                _ => {}
            }
            return Scope::Keyword;
        }
        if prev == "fn" {
            self.pending = Some(Bracket::Params);
            return Scope::Function;
        }
        let next_tok = self.next_significant(idx).map(|t| t.text.as_str()).unwrap_or("");
        if self.in_params() && next_tok == ":" {
            return Scope::Variable;
        }
        if self.in_struct_body() && next_tok == ":" {
            return Scope::Variable;
        }
        if next == Some('(')
            && prev != "::"
            && name.chars().next().map_or(false, |c| c.is_lowercase() || c == '_')
        {
            return Scope::Support;
        }
        Scope::Text
    }

    fn c_ident(&mut self, name: &str, prev: &str, next: Option<char>, idx: usize, base: Scope) -> Scope {
        if C_KEYWORDS.contains(&name) || (self.lang == Language::Cpp && CPP_KEYWORDS.contains(&name)) {
            if self.lang == Language::Cpp && name == "class" {
                self.pending = Some(Bracket::ClassBody);
            }
            return Scope::Keyword;
        }
        if C_CONSTANTS.contains(&name) {
            return Scope::Constant;
        }
        if self.lang == Language::Cpp && (prev == "class" || prev == "struct") && self.pending == Some(Bracket::ClassBody) {
            return Scope::Class;
        }
        if self.lang == Language::Cpp && self.pending == Some(Bracket::ClassBody) && matches!(prev, "public" | "private" | "protected" | ":" | ",") {
            return Scope::String;
        }
        let next_tok = self.next_significant(idx).map(|t| t.text.as_str()).unwrap_or("");
        if prev == "." || prev == "->" {
            return Scope::Variable;
        }
        if self.in_params() && matches!(next_tok, "," | ")" | "[" | "=") {
            return Scope::Variable;
        }
        if next == Some('(') || (next == Some('<') && self.template_call(idx)) {
            // Definition when preceded by a type-like token.
            let is_definition = prev.chars().last().map_or(false, |c| is_ident_char(c) || c == '*' || c == '&' || c == '~')
                && !matches!(prev, "return" | "sizeof" | "new" | "delete" | "throw" | "else" | "do");
            if is_definition || prev == ":" && self.lang == Language::Cpp {
                self.pending = Some(Bracket::Params);
            }
            if C_LIB_FUNCTIONS.contains(&name) && !is_definition {
                return Scope::Support;
            }
            return Scope::Function;
        }
        if prev == "~" && self.lang == Language::Cpp {
            return Scope::Function;
        }
        base
    }

    fn template_call(&self, idx: usize) -> bool {
        // ident<...>( on the same line
        let mut depth = 0;
        for tok in &self.tokens[idx + 1..] {
            match tok.text.as_str() {
                "<" => depth += 1,
                ">" => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                "\n" | ";" | "{" => return false,
                _ => {}
            }
        }
        let mut after_close = false;
        depth = 0;
        for tok in &self.tokens[idx + 1..] {
            if after_close {
                if tok.text.trim().is_empty() {
                    continue;
                }
                return tok.text == "(";
            }
            match tok.text.as_str() {
                "<" => depth += 1,
                ">" => {
                    depth -= 1;
                    if depth == 0 {
                        after_close = true;
                    }
                }
                _ => {}
            }
        }
        false
    }

    fn java_ident(&mut self, name: &str, prev: &str, next: Option<char>, idx: usize, base: Scope) -> Scope {
        if JAVA_KEYWORDS.contains(&name) {
            if name == "class" || name == "interface" || name == "enum" {
                self.pending = Some(Bracket::ClassBody);
            }
            return Scope::Keyword;
        }
        if matches!(name, "true" | "false" | "null") {
            return Scope::Constant;
        }
        if prev == "@" {
            return Scope::Variable;
        }
        if prev == "import" || prev == "package" {
            return if prev == "import" { Scope::Class } else { Scope::Text };
        }
        if prev == "." && self.prev_significant(idx).is_some() {
            // Part of a qualified name after import.
            let mut i = idx;
            let mut is_import = false;
            while i > 0 {
                i -= 1;
                let t = &self.tokens[i];
                if t.text.trim().is_empty() {
                    continue;
                }
                if t.text == "\n" || t.text == ";" {
                    break;
                }
                if t.text == "import" {
                    is_import = true;
                    break;
                }
            }
            if is_import {
                return Scope::Class;
            }
        }
        if matches!(prev, "extends" | "implements") || (prev == "," && self.pending == Some(Bracket::ClassBody)) {
            return Scope::String;
        }
        if matches!(prev, "class" | "interface" | "enum") {
            return Scope::Class;
        }
        let next_tok = self.next_significant(idx).map(|t| t.text.as_str()).unwrap_or("");
        if next == Some('(') {
            let is_definition = prev.chars().last().map_or(false, |c| is_ident_char(c) || c == '>' || c == ']')
                && !matches!(prev, "return" | "new" | "throw" | "else");
            if is_definition {
                self.pending = Some(Bracket::Params);
            }
            return Scope::Function;
        }
        if self.in_params() && matches!(next_tok, "," | ")" | "[" | "=") {
            return Scope::Variable;
        }
        if name.chars().next().map_or(false, |c| c.is_uppercase()) {
            if name.chars().all(|c| c.is_uppercase() || c.is_ascii_digit() || c == '_') && name.len() > 1 {
                // Constants, unless being declared.
                let declared = prev.chars().last().map_or(false, |c| is_ident_char(c) || c == '>' || c == ']');
                return if declared { base } else { Scope::Constant };
            }
            return Scope::Class;
        }
        base
    }

    fn js_ident(&mut self, name: &str, prev: &str, next: Option<char>, idx: usize, base: Scope) -> Scope {
        if JS_KEYWORDS.contains(&name) {
            if name == "class" {
                self.pending = Some(Bracket::ClassBody);
            }
            if name == "function" {
                self.pending = Some(Bracket::Params);
            }
            return Scope::Keyword;
        }
        if JS_OPERATOR_WORDS.contains(&name) {
            return Scope::Text;
        }
        if JS_CONSTANTS.contains(&name) {
            return Scope::Constant;
        }
        if name == "this" {
            return Scope::Variable;
        }
        if prev == "extends" {
            return Scope::String;
        }
        if prev == "class" {
            return Scope::Class;
        }
        let next_tok = self.next_significant(idx).map(|t| t.text.as_str()).unwrap_or("");
        if prev == "." {
            if next == Some('(') {
                return if JS_SUPPORT_FUNCTIONS.contains(&name) { Scope::Support } else { Scope::Function };
            }
            return base;
        }
        if next == Some('(') {
            if prev == "function" || (self.in_class_body() && self.stack.last() == Some(&Bracket::ClassBody)) || matches!(prev, "get" | "set" | "static" | "async") {
                self.pending = Some(Bracket::Params);
                return Scope::Function;
            }
            if JS_SUPPORT_FUNCTIONS.contains(&name) {
                return Scope::Support;
            }
            if name.chars().next().map_or(false, |c| c.is_uppercase()) {
                return Scope::Class;
            }
            return Scope::Function;
        }
        if self.in_params() {
            return base;
        }
        if next_tok == ":" && prev == "{" || prev == "," && self.stack.last() == Some(&Bracket::Other) && next_tok == ":" {
            return base;
        }
        if name.chars().next().map_or(false, |c| c.is_uppercase()) {
            return Scope::Class;
        }
        if name == "console" || name == "window" || name == "document" || name == "Math" || name == "JSON" {
            return base;
        }
        if next_tok == "=>" {
            return base;
        }
        Scope::Variable
    }

    fn go_ident(&mut self, name: &str, prev: &str, next: Option<char>, idx: usize) -> Scope {
        if GO_KEYWORDS.contains(&name) {
            if name == "struct" {
                self.pending = Some(Bracket::StructBody);
            }
            return Scope::Keyword;
        }
        if GO_CONSTANTS.contains(&name) {
            return Scope::Constant;
        }
        if prev == "func" {
            self.pending = Some(Bracket::Params);
            return Scope::Function;
        }
        let next_tok = self.next_significant(idx).map(|t| t.text.as_str()).unwrap_or("");
        if next == Some('(') {
            if GO_BUILTINS.contains(&name) && prev != "." {
                return Scope::Support;
            }
            if prev == ")" {
                // Method receiver: func (r *T) Name(
                self.pending = Some(Bracket::Params);
            }
            return Scope::Function;
        }
        if self.in_params() {
            // Parameter names are followed by a comma or a type.
            if next_tok == "," || next_tok.chars().next().map_or(false, |c| is_ident_start(c) || c == '*' || c == '[') {
                return Scope::Variable;
            }
            return Scope::Text;
        }
        if self.in_struct_body() && (next_tok == "," || next_tok.chars().next().map_or(false, |c| is_ident_start(c) || c == '*' || c == '[')) && prev != "." {
            return Scope::Variable;
        }
        if next_tok == ":=" || (next_tok == "," && self.decl_ahead(idx)) {
            return Scope::Variable;
        }
        Scope::Text
    }

    fn decl_ahead(&self, idx: usize) -> bool {
        // a, b := ...
        for tok in &self.tokens[idx + 1..] {
            match tok.text.as_str() {
                ":=" => return true,
                "\n" | ";" | "=" | "(" | ")" | "{" | "}" => return false,
                _ => {}
            }
        }
        false
    }
}

pub fn highlight(content: &str, lang: Language) -> Vec<Vec<Segment>> {
    let mut lexer = Lexer { lang, tokens: Vec::new() };
    lexer.tokenize(content);
    let mut e = Emitter::new();
    let classifier = Classifier {
        lang,
        tokens: &lexer.tokens,
        stack: Vec::new(),
        pending: None,
        attribute_first: false,
    };
    classifier.run(&mut e);
    e.finish()
}
