    "staticmethod", "classmethod", "vars", "dir", "globals", "locals", "callable", "compile",
    "eval", "exec", "exit", "quit", "help", "memoryview", "bytearray", "bytes", "frozenset",
    "slice", "complex", "ascii", "breakpoint", "__import__",
];

#[derive(Clone, Copy, PartialEq, Eq)]
enum Ctx {
    Params,
    ClassHeader,
    Other,
}

struct State {
    stack: Vec<Ctx>,
    pending: Option<Ctx>,
    /// Statement so far contains a `for`/`async for` (so `in` is a keyword).
    for_seen: bool,
    /// Next token starts a statement (used for docstrings).
    statement_start: bool,
    after_dot: bool,
}

pub fn highlight(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    let mut st = State { stack: Vec::new(), pending: None, for_seen: false, statement_start: true, after_dot: false };
    while let Some(c) = cur.peek() {
        if c == '\n' {
            cur.advance(1);
            e.push(Scope::Text, "\n");
            st.for_seen = false;
            st.statement_start = true;
            st.pending = None;
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace() && c != '\n');
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '#' {
            let text = cur.take_line();
            e.push(Scope::Comment, text);
            continue;
        }
        // Strings (with optional prefix).
        if c == '"' || c == '\'' || (is_ident_start(c) && string_prefix(&cur).is_some()) {
            let docstring = st.statement_start;
            let prefix_len = if c == '"' || c == '\'' { 0 } else { string_prefix(&cur).unwrap() };
            string(&mut cur, &mut e, prefix_len, docstring);
            st.statement_start = false;
            st.after_dot = false;
            continue;
        }
        st.statement_start = false;
        if c.is_ascii_digit() || (c == '.' && cur.peek_at(1).map_or(false, |d| d.is_ascii_digit())) {
            let n = number(&mut cur);
            e.push(Scope::Constant, n);
            st.after_dot = false;
            continue;
        }
        if c == '@' {
            cur.advance(1);
            e.push(Scope::Text, "@");
            let name = cur.take_while(|c| is_ident_char(c) || c == '.');
            e.push(Scope::Support, name);
            continue;
        }
        if is_ident_start(c) {
            let ident = cur.take_while(is_ident_char);
            let scope = classify(ident, &mut st, &cur);
            e.push(scope, ident);
            st.after_dot = false;
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        let p = cur.slice(start);
        st.after_dot = p == ".";
        match p {
            "(" => {
                let ctx = match st.pending.take() {
                    Some(Ctx::Params) => Ctx::Params,
                    Some(Ctx::ClassHeader) => {
                        st.pending = Some(Ctx::ClassHeader);
                        Ctx::ClassHeader
                    }
                    _ => Ctx::Other,
                };
                st.stack.push(ctx);
                e.push(if ctx == Ctx::ClassHeader { Scope::Meta } else { Scope::Text }, p);
            }
            "[" | "{" => {
                st.stack.push(Ctx::Other);
                e.push(Scope::Text, p);
            }
            ")" | "]" | "}" => {
                let ctx = st.stack.pop();
                e.push(if ctx == Some(Ctx::ClassHeader) { Scope::Meta } else { Scope::Text }, p);
            }
            ":" => {
                if st.pending == Some(Ctx::ClassHeader) && st.stack.is_empty() {
                    st.pending = None;
                    e.push(Scope::Meta, p);
                } else {
                    e.push(Scope::Text, p);
                }
            }
            _ => e.push(Scope::Text, p),
        }
    }
    e.finish()
}

fn string_prefix(cur: &Cursor) -> Option<usize> {
    let rest = cur.rest();
    for n in [2usize, 1] {
        let prefix: String = rest.chars().take(n).collect();
        if prefix.chars().count() < n {
            continue;
        }
        let lower = prefix.to_lowercase();
        let valid = match n {
            1 => matches!(lower.as_str(), "r" | "b" | "f" | "u"),
