        }
        if ident.chars().next().map_or(false, |c| c.is_uppercase()) {
            return Scope::Text;
        }
        return Scope::Function;
    }
    // Keyword arguments: name=value inside a call.
    if next == Some('=') && st.stack.last() == Some(&Ctx::Other) && !cur.rest().trim_start().starts_with("==") {
        return Scope::Variable;
    }
    Scope::Text
}

fn next_significant(cur: &Cursor) -> Option<char> {
    cur.rest().chars().find(|c| !c.is_whitespace() || *c == '\n')
}
