    let mut cur = Cursor::new(content);
    let mut pos = Pos::Command;
    let mut last_cmd = String::new();
    while let Some(c) = cur.peek() {
        if c == '\n' {
            cur.advance(1);
            e.push(Scope::Text, "\n");
            pos = Pos::Command;
            last_cmd.clear();
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace() && c != '\n');
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '#' {
            let text = cur.take_line();
            e.push(Scope::Comment, text);
            continue;
        }
        if c == '"' {
            double_quoted(&mut cur, &mut e);
            pos = Pos::Argument;
            continue;
        }
        if c == '\'' {
            let start = cur.byte_pos();
            cur.advance(1);
            let body = cur.take_while(|c| c != '\'').to_string();
            let _ = start;
            e.push(Scope::Text, "'");
            e.push(Scope::String, &body);
            if cur.peek() == Some('\'') {
                cur.advance(1);
                e.push(Scope::Text, "'");
            }
            pos = Pos::Argument;
            continue;
        }
        if c == '$' {
            dollar(&mut cur, &mut e, false);
            pos = Pos::Argument;
            continue;
        }
        if c == '`' {
            cur.advance(1);
            e.push(Scope::Text, "`");
            pos = Pos::Command;
            continue;
        }
        // Words.
        if is_word_char(c) {
            let word = cur.take_while(is_word_char).to_string();
            // Assignment: NAME=value
            if pos == Pos::Command && is_ident_start(word.chars().next().unwrap_or(' ')) && word.chars().all(is_ident_char) && cur.peek() == Some('=') {
                e.push(Scope::Variable, &word);
                cur.advance(1);
                e.push(Scope::Text, "=");
                assignment_value(&mut cur, &mut e);
                pos = Pos::Argument;
                continue;
            }
            if word.contains('=') && pos == Pos::Command {
                let (name, rest) = word.split_once('=').unwrap();
                if !name.is_empty() && name.chars().all(is_ident_char) {
                    e.push(Scope::Variable, name);
                    e.push(Scope::Text, "=");
                    e.push(Scope::String, rest);
                    pos = Pos::Argument;
                    continue;
                }
            }
            if pos == Pos::Command {
                if KEYWORDS.contains(&word.as_str()) {
                    e.push(Scope::Keyword, &word);
                    if matches!(word.as_str(), "local" | "export" | "declare" | "typeset" | "readonly") {
                        last_cmd = word.clone();
                        pos = Pos::Argument;
                    } else if matches!(word.as_str(), "for" | "case" | "select" | "function") {
                        last_cmd = word.clone();
                        pos = Pos::Argument;
                    }
                    continue;
                }
                last_cmd = word.clone();
                if BUILTINS.contains(&word.as_str()) {
                    e.push(Scope::Support, &word);
                } else {
                    e.push(Scope::Function, &word);
                }
                pos = Pos::Argument;
                continue;
            }
            // Arguments.
            match last_cmd.as_str() {
                "function" => {
                    e.push(Scope::Function, &word);
                    last_cmd.clear();
                }
                "for" | "select" => {
                    if word == "in" {
                        e.push(Scope::Keyword, &word);
                        last_cmd.clear();
                    } else {
                        e.push(Scope::Text, &word);
                    }
                }
                "local" | "export" | "declare" | "typeset" | "readonly" => {
                    if word.starts_with('-') {
                        e.push(Scope::Variable, &word);
                    } else {
                        e.push(Scope::Variable, &word);
                    }
                }
                _ => {
                    if KEYWORDS.contains(&word.as_str()) && matches!(word.as_str(), "then" | "do" | "in" | "done" | "fi" | "else" | "elif") {
                        e.push(Scope::Keyword, &word);
                    } else if BUILTINS.contains(&word.as_str()) && (word == "]" || word == "]]") {
                        e.push(Scope::Support, &word);
                    } else if word.starts_with('-') && word.len() > 1 && last_cmd != "set" {
                        e.push(Scope::Variable, &word);
                    } else {
                        e.push(Scope::Text, &word);
                    }
