fn assignment_value(cur: &mut Cursor, e: &mut Emitter) {
    // The value is an unquoted word (string) or handled by the main loop
    // (quotes, variables).
    if let Some(c) = cur.peek() {
        if is_word_char(c) && c != '$' {
            let word = cur.take_while(|c| is_word_char(c) && c != '$');
            e.push(Scope::String, word);
        }
    }
}

fn dollar(cur: &mut Cursor, e: &mut Emitter, in_string: bool) {
    cur.advance(1);
    e.push(Scope::Text, "$");
    match cur.peek() {
        Some('{') => {
            cur.advance(1);
            e.push(if in_string { Scope::String } else { Scope::Text }, "{");
            let name = cur.take_while(|c| is_ident_char(c) || c == '#' || c == '!' || c == '@' || c == '*');
            e.push(Scope::Variable, name);
            let rest = cur.take_while(|c| c != '}' && c != '\n' && c != '"');
            e.push(Scope::Text, rest);
            if cur.peek() == Some('}') {
                cur.advance(1);
                e.push(if in_string { Scope::String } else { Scope::Text }, "}");
            }
        }
        Some('(') => {
            cur.advance(1);
            e.push(if in_string { Scope::String } else { Scope::Text }, "(");
            if cur.peek() == Some('(') {
                cur.advance(1);
                e.push(Scope::Text, "(");
                let body = cur.take_until("))");
                e.push(Scope::Text, body);
                return;
            }
            // Command substitution: first word is a command.
            let mut first = true;
            loop {
                match cur.peek() {
                    None | Some('\n') => break,
                    Some(')') => {
                        cur.advance(1);
                        e.push(if in_string { Scope::String } else { Scope::Text }, ")");
                        break;
                    }
                    Some(c) if c.is_whitespace() => {
                        let ws = cur.take_while(|c| c == ' ' || c == '\t');
                        e.push(Scope::Text, ws);
                    }
                    Some('$') => dollar(cur, e, in_string),
                    Some('"') => double_quoted(cur, e),
                    Some(_) => {
                        let word = cur.take_while(|c| is_word_char(c) && c != ')');
                        if word.is_empty() {
                            cur.advance(1);
                            continue;
                        }
                        if first {
                            e.push(if BUILTINS.contains(&word) { Scope::Support } else { Scope::Function }, word);
                            first = false;
                        } else if word.starts_with('-') {
                            e.push(Scope::Variable, word);
                        } else {
                            e.push(Scope::Text, word);
                        }
                    }
                }
            }
        }
        Some(c) if is_ident_char(c) || matches!(c, '#' | '?' | '@' | '*' | '!' | '$' | '-') => {
            if c.is_ascii_digit() || !is_ident_char(c) {
                let start = cur.byte_pos();
                cur.advance(1);
                e.push(Scope::Variable, cur.slice(start));
            } else {
                let name = cur.take_while(is_ident_char);
                e.push(Scope::Variable, name);
            }
        }
        _ => {}
    }
}

fn double_quoted(cur: &mut Cursor, e: &mut Emitter) {
    cur.advance(1);
    e.push(Scope::Text, "\"");
    let mut literal = String::new();
    loop {
        let Some(c) = cur.peek() else {
            break;
        };
        match c {
            '"' => {
                cur.advance(1);
                if !literal.is_empty() {
                    e.push(Scope::String, &literal);
                    literal.clear();
                }
                e.push(Scope::Text, "\"");
                return;
            }
            '\\' => {
                let start = cur.byte_pos();
                cur.advance(2);
                if !literal.is_empty() {
                    e.push(Scope::String, &literal);
                    literal.clear();
                }
                e.push(Scope::Escape, cur.slice(start));
            }
            '$' => {
                if !literal.is_empty() {
                    e.push(Scope::String, &literal);
                    literal.clear();
                }
                dollar(cur, e, true);
            }
            _ => {
                literal.push(c);
                cur.advance(1);
            }
        }
    }
    if !literal.is_empty() {
        e.push(Scope::String, &literal);
    }
}
