//! Markdown lexer (line oriented).

use super::{Emitter, Scope, Segment};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Block {
    None,
    List,
    Quote,
}

pub fn highlight(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let lines: Vec<&str> = content.split('\n').collect();
    let mut block = Block::None;
    let mut in_fence: Option<String> = None;
    let mut prev_blank = true;
    let mut prev_was_text = false;
    for (i, line) in lines.iter().enumerate() {
        if i > 0 {
            e.push(Scope::Text, "\n");
        }
        let trimmed = line.trim_start();
        if let Some(fence) = &in_fence {
            if trimmed.starts_with(fence.as_str()) && trimmed.trim_end().chars().all(|c| c == fence.chars().next().unwrap()) {
                e.push(Scope::Text, line);
                in_fence = None;
            } else {
                e.push(Scope::Text, line);
            }
            prev_blank = false;
            prev_was_text = false;
            continue;
        }
        if trimmed.is_empty() {
            e.push(Scope::Text, line);
            block = Block::None;
            prev_blank = true;
            prev_was_text = false;
            continue;
        }
        // Fenced code block start.
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            let fence_char = trimmed.chars().next().unwrap();
            let fence_len = trimmed.chars().take_while(|c| *c == fence_char).count();
            let indent = &line[..line.len() - trimmed.len()];
            let fence: String = trimmed.chars().take(fence_len).collect();
            let info = &trimmed[fence_len..];
            e.push(Scope::Text, indent);
            e.push(Scope::Text, &fence);
            let info_trim = info.trim_start();
            e.push(Scope::Text, &info[..info.len() - info_trim.len()]);
            e.push(Scope::Constant, info_trim);
            in_fence = Some(fence);
            block = Block::None;
            prev_blank = false;
            prev_was_text = false;
            continue;
        }
        // Setext heading underline.
        if prev_was_text && block == Block::None && !trimmed.is_empty()
            && (trimmed.trim_end().chars().all(|c| c == '=') || trimmed.trim_end().chars().all(|c| c == '-'))
        {
            e.push(Scope::Function, line);
            prev_blank = false;
            prev_was_text = false;
            continue;
        }
        // ATX heading.
        if trimmed.starts_with('#') {
            let hashes: String = trimmed.chars().take_while(|c| *c == '#').collect();
            if hashes.len() <= 6 && trimmed[hashes.len()..].starts_with(' ') || trimmed.len() == hashes.len() {
                let indent = &line[..line.len() - trimmed.len()];
                e.push(Scope::Text, indent);
                e.push(Scope::Function, &hashes);
                let rest = &trimmed[hashes.len()..];
                let text = rest.trim_start();
                e.push(Scope::Text, &rest[..rest.len() - text.len()]);
                // Closing hashes.
                let body = text.trim_end();
                let closing = body.rfind(|c| c != '#').map(|i| &body[i + 1..]).unwrap_or(body);
                let main = &body[..body.len() - closing.len()];
                let main_trim = main.trim_end();
                e.push(Scope::Function, main_trim);
                e.push(Scope::Text, &main[main_trim.len()..]);
                e.push(Scope::Function, closing);
                e.push(Scope::Text, &text[body.len()..]);
                block = Block::None;
                prev_blank = false;
                prev_was_text = false;
                continue;
            }
        }
        // Thematic break.
        if prev_blank && trimmed.trim_end().len() >= 3 && (trimmed.trim_end().chars().all(|c| c == '-') || trimmed.trim_end().chars().all(|c| c == '*') || trimmed.trim_end().chars().all(|c| c == '_')) {
            e.push(Scope::Text, line);
            prev_blank = false;
            prev_was_text = false;
            continue;
        }
        // Link reference definition.
        if trimmed.starts_with('[') && trimmed.contains("]:") && block == Block::None {
            e.push(Scope::Constant, line);
            prev_blank = false;
            prev_was_text = false;
            continue;
        }
        // Block quote.
        if trimmed.starts_with('>') && block != Block::List {
            block = Block::Quote;
        } else if is_list_item(trimmed) && (block != Block::Quote || prev_blank) {
            block = Block::List;
        }
        let base = match block {
            Block::None => Scope::Text,
            Block::List => Scope::Variable,
            Block::Quote => Scope::Constant,
        };
        inline(line, base, &mut e);
        prev_blank = false;
        prev_was_text = block == Block::None;
    }
    e.finish()
}

fn is_list_item(trimmed: &str) -> bool {
    let mut chars = trimmed.chars();
    match chars.next() {
        Some('-') | Some('*') | Some('+') => matches!(chars.next(), Some(' ') | Some('\t')),
        Some(c) if c.is_ascii_digit() => {
            let digits = trimmed.chars().take_while(|c| c.is_ascii_digit()).count();
            let rest = &trimmed[digits..];
            (rest.starts_with(". ") || rest.starts_with(") ")) && digits <= 9
        }
        _ => false,
    }
}

fn inline(line: &str, base: Scope, e: &mut Emitter) {
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    let mut literal = String::new();
    let flush = |literal: &mut String, e: &mut Emitter| {
        if !literal.is_empty() {
            e.push(base, literal);
            literal.clear();
        }
    };
    while i < chars.len() {
        let c = chars[i];
        let prev = if i > 0 { chars[i - 1] } else { ' ' };
        // Inline code.
        if c == '`' {
            let run = chars[i..].iter().take_while(|c| **c == '`').count();
            if let Some(end) = find_run(&chars, i + run, '`', run) {
                flush(&mut literal, e);
                let text: String = chars[i..end + run].iter().collect();
                e.push(Scope::String, &text);
                i = end + run;
                continue;
            }
        }
        // Images and links.
        if c == '!' && chars.get(i + 1) == Some(&'[') {
            if let Some(end) = link_end(&chars, i + 1) {
                flush(&mut literal, e);
                let text: String = chars[i..end].iter().collect();
                e.push(Scope::Constant, &text);
                i = end;
                continue;
            }
        }
        if c == '[' {
            if let Some(end) = link_end(&chars, i) {
                flush(&mut literal, e);
                let text: String = chars[i..end].iter().collect();
                e.push(Scope::Constant, &text);
                i = end;
                continue;
            }
        }
        // Autolinks and inline html.
        if c == '<' {
            if let Some(close) = chars[i..].iter().position(|c| *c == '>') {
                let inner: String = chars[i + 1..i + close].iter().collect();
                if inner.contains("://") || (inner.contains('@') && !inner.contains(' ')) {
                    flush(&mut literal, e);
                    let text: String = chars[i..=i + close].iter().collect();
                    e.push(Scope::Constant, &text);
                    i += close + 1;
                    continue;
                }
                if inner.chars().next().map_or(false, |c| c.is_ascii_alphabetic() || c == '/') && !inner.contains('\n') {
                    flush(&mut literal, e);
                    html_tag(&inner, base, e);
                    i += close + 1;
                    continue;
                }
            }
        }
        // Emphasis.
        if (c == '*' || c == '_') && (c == '*' || !prev.is_alphanumeric()) {
            let run = chars[i..].iter().take_while(|d| **d == c).count().min(3);
            if run >= 1 && chars.get(i + run).map_or(false, |d| !d.is_whitespace()) {
                if let Some(end) = find_run(&chars, i + run, c, run) {
                    if chars[end - 1] != ' ' && (c == '*' || chars.get(end + run).map_or(true, |d| !d.is_alphanumeric())) {
                        flush(&mut literal, e);
                        let text: String = chars[i..end + run].iter().collect();
                        let scope = if run >= 2 { Scope::Class } else { Scope::Keyword };
                        e.push(scope, &text);
                        i = end + run;
                        continue;
                    }
                }
            }
        }
        literal.push(c);
        i += 1;
    }
    flush(&mut literal, e);
}

fn html_tag(inner: &str, base: Scope, e: &mut Emitter) {
    e.push(base, "<");
    let mut rest = inner;
    if let Some(r) = rest.strip_prefix('/') {
        e.push(base, "/");
        rest = r;
    }
    let name_len = rest.find(|c: char| !(c.is_alphanumeric() || c == '-' || c == ':')).unwrap_or(rest.len());
    e.push(Scope::Variable, &rest[..name_len]);
    e.push(base, &rest[name_len..]);
    e.push(base, ">");
}

/// Find the start index of the next run of `n` `c` characters at or after `from`.
fn find_run(chars: &[char], from: usize, c: char, n: usize) -> Option<usize> {
    let mut i = from;
    while i + n <= chars.len() {
        if chars[i..i + n].iter().all(|d| *d == c) && chars.get(i + n) != Some(&c) {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// Returns the end (exclusive) of a link starting at `[`.
fn link_end(chars: &[char], start: usize) -> Option<usize> {
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            }
            _ => {}
        }
        i += 1;
    }
    if i >= chars.len() {
        return None;
    }
    let after = i + 1;
    match chars.get(after) {
        Some('(') => {
            let close = chars[after..].iter().position(|c| *c == ')')?;
            Some(after + close + 1)
        }
        Some('[') => {
            let close = chars[after..].iter().position(|c| *c == ']')?;
            Some(after + close + 1)
        }
        _ => None,
    }
}
