//! Lexers for data formats and a few other languages: JSON, YAML, Makefile,
//! CSS, Lua, SQL, Ruby, HTML/XML.

use super::{clike, is_ident_char, is_ident_start, Cursor, Emitter, Language, Scope, Segment};

/// Emit a quoted string: quotes are plain, the content uses `scope`.
fn quoted(cur: &mut Cursor, e: &mut Emitter, quote: char, scope: Scope, escapes: bool) {
    cur.advance(1);
    e.push(Scope::Text, &quote.to_string());
    let mut literal = String::new();
    while let Some(c) = cur.peek() {
        if c == '\n' {
            break;
        }
        if c == '\\' && escapes {
            let start = cur.byte_pos();
            cur.advance(2);
            if !literal.is_empty() {
                e.push(scope, &literal);
                literal.clear();
            }
            e.push(Scope::Escape, cur.slice(start));
            continue;
        }
        if c == quote {
            cur.advance(1);
            if !literal.is_empty() {
                e.push(scope, &literal);
                literal.clear();
            }
            e.push(Scope::Text, &quote.to_string());
            return;
        }
        literal.push(c);
        cur.advance(1);
    }
    if !literal.is_empty() {
        e.push(scope, &literal);
    }
}

fn number_like(s: &str) -> bool {
    let t = s.strip_prefix('-').unwrap_or(s);
    !t.is_empty()
        && t.chars().next().map_or(false, |c| c.is_ascii_digit())
        && t.chars().all(|c| c.is_ascii_hexdigit() || matches!(c, '.' | 'x' | 'e' | 'E' | '+' | '-' | '_'))
}

pub fn json(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    while let Some(c) = cur.peek() {
        match c {
            '"' => quoted(&mut cur, &mut e, '"', Scope::String, true),
            c if c.is_ascii_digit() || c == '-' => {
                let n = cur.take_while(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '+'));
                e.push(Scope::Constant, n);
            }
            c if is_ident_start(c) => {
                let w = cur.take_while(is_ident_char);
                let scope = if matches!(w, "true" | "false" | "null") { Scope::Constant } else { Scope::Text };
                e.push(scope, w);
            }
            '/' if cur.starts_with("//") => {
                let t = cur.take_line();
                e.push(Scope::Comment, t);
            }
            '/' if cur.starts_with("/*") => {
                let t = cur.take_until("*/");
                e.push(Scope::Comment, t);
            }
            _ => {
                let start = cur.byte_pos();
                cur.advance(1);
                e.push(Scope::Text, cur.slice(start));
            }
        }
    }
    e.finish()
}

pub fn yaml(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    for (i, line) in content.split('\n').enumerate() {
        if i > 0 {
            e.push(Scope::Text, "\n");
        }
        let trimmed = line.trim_start();
        let indent = &line[..line.len() - trimmed.len()];
        e.push(Scope::Text, indent);
        if trimmed.starts_with('#') {
            e.push(Scope::Comment, trimmed);
            continue;
        }
        let mut rest = trimmed;
        if rest == "---" || rest == "..." {
            e.push(Scope::Text, rest);
            continue;
        }
        if rest.starts_with("- ") || rest == "-" {
            e.push(Scope::Text, "-");
            rest = &rest[1..];
            let after = rest.trim_start();
            e.push(Scope::Text, &rest[..rest.len() - after.len()]);
            rest = after;
        }
        // key: value
        if let Some(colon) = find_key_colon(rest) {
            let key = &rest[..colon];
            if !key.is_empty() && !key.starts_with('"') && !key.starts_with('\'') && !key.starts_with('[') && !key.starts_with('{') {
                e.push(Scope::Variable, key);
                e.push(Scope::Text, ":");
                rest = &rest[colon + 1..];
            } else if key.starts_with('"') || key.starts_with('\'') {
                e.push(Scope::Text, &key[..1]);
                e.push(Scope::String, &key[1..key.len().saturating_sub(1)]);
                e.push(Scope::Text, &key[key.len().saturating_sub(1)..]);
                e.push(Scope::Text, ":");
                rest = &rest[colon + 1..];
            }
        }
        yaml_value(rest, &mut e);
    }
    e.finish()
}

fn find_key_colon(s: &str) -> Option<usize> {
    // A key ends with ':' followed by a space or end of line.
    let bytes = s.as_bytes();
    let mut in_quote: Option<u8> = None;
    for (i, &b) in bytes.iter().enumerate() {
        match in_quote {
            Some(q) => {
                if b == q {
                    in_quote = None;
                }
            }
            None => {
                if (b == b'"' || b == b'\'') && i == 0 {
                    in_quote = Some(b);
                } else if b == b':' && (i + 1 == bytes.len() || bytes[i + 1] == b' ') {
                    return Some(i);
                } else if b == b'#' && i > 0 && bytes[i - 1] == b' ' {
                    return None;
                }
            }
        }
    }
    None
}

fn yaml_value(rest: &str, e: &mut Emitter) {
    let value = rest.trim_start();
    e.push(Scope::Text, &rest[..rest.len() - value.len()]);
    if value.is_empty() {
        return;
    }
    // Trailing comment.
    let (value, comment) = match value.find(" #") {
        Some(i) if !value.starts_with('"') && !value.starts_with('\'') => (&value[..i], &value[i..]),
        _ => (value, ""),
    };
    if value.starts_with('"') || value.starts_with('\'') {
        let mut cur = Cursor::new(value);
        let q = value.chars().next().unwrap();
        quoted(&mut cur, e, q, Scope::String, q == '"');
        e.push(Scope::Text, cur.rest());
    } else if matches!(value, "true" | "false" | "null" | "~" | "yes" | "no" | "on" | "off" | "True" | "False" | "Null" | "TRUE" | "FALSE" | "NULL" | "Yes" | "No") || number_like(value) {
        e.push(Scope::Constant, value);
    } else if value.starts_with('&') || value.starts_with('*') || value.starts_with('!') || value.starts_with('|') || value.starts_with('>') || value.starts_with('[') || value.starts_with('{') {
        e.push(Scope::Text, value);
    } else {
        e.push(Scope::String, value);
    }
    if !comment.is_empty() {
        let c = comment.trim_start();
        e.push(Scope::Text, &comment[..comment.len() - c.len()]);
        e.push(Scope::Comment, c);
    }
}

pub fn makefile(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    for (i, line) in content.split('\n').enumerate() {
        if i > 0 {
            e.push(Scope::Text, "\n");
        }
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') {
            e.push(Scope::Text, &line[..line.len() - trimmed.len()]);
            e.push(Scope::Comment, trimmed);
            continue;
        }
        if line.starts_with('\t') {
            // Recipe line.
            e.push(Scope::Text, "\t");
            let body = &line[1..];
            let body_trim = body.trim_start();
            e.push(Scope::Text, &body[..body.len() - body_trim.len()]);
            let mut first = true;
            let mut cur = Cursor::new(body_trim);
            while let Some(c) = cur.peek() {
                if c.is_whitespace() {
                    let ws = cur.take_while(|c| c.is_whitespace());
                    e.push(Scope::Text, ws);
                    continue;
                }
                if c == '$' {
                    make_variable(&mut cur, &mut e);
                    continue;
                }
                if c == '"' || c == '\'' {
                    quoted(&mut cur, &mut e, c, Scope::String, c == '"');
                    continue;
                }
                let word = cur.take_while(|c| !c.is_whitespace() && c != '$');
                if first {
                    e.push(Scope::Function, word);
                    first = false;
                } else if word.starts_with('-') {
                    e.push(Scope::Variable, word);
                } else {
                    e.push(Scope::Text, word);
                }
            }
            continue;
        }
        // Variable assignment.
        if let Some(pos) = line.find(|c| c == '=' || c == ':') {
            let (name, rest) = line.split_at(pos);
            let name_trim = name.trim();
            if rest.starts_with(":=") || rest.starts_with("::=") || rest.starts_with("?=") || rest.starts_with("+=") || rest.starts_with("!=") || (rest.starts_with('=') && !name_trim.is_empty()) {
                let op_len = if rest.starts_with("::=") { 3 } else if rest.starts_with(":=") || rest.starts_with("?=") || rest.starts_with("+=") || rest.starts_with("!=") { 2 } else { 1 };
                let lead = &name[..name.len() - name.trim_start().len()];
                e.push(Scope::Text, lead);
                e.push(Scope::Variable, name_trim);
                e.push(Scope::Text, &name[lead.len() + name_trim.len()..]);
                e.push(Scope::Text, &rest[..op_len]);
                let value = &rest[op_len..];
                let value_trim = value.trim_start();
                e.push(Scope::Text, &value[..value.len() - value_trim.len()]);
                make_value(value_trim, &mut e);
                continue;
            }
            if rest.starts_with(':') && !name_trim.is_empty() {
                // Target: dependencies
                let lead = &name[..name.len() - name.trim_start().len()];
                e.push(Scope::Text, lead);
                for (j, target) in name_trim.split(' ').enumerate() {
                    if j > 0 {
                        e.push(Scope::Text, " ");
                    }
                    if target.starts_with('.') {
                        e.push(Scope::Keyword, target);
                    } else {
                        e.push(Scope::Function, target);
                    }
                }
                e.push(Scope::Text, &name[lead.len() + name_trim.len()..]);
                e.push(Scope::Text, ":");
                let deps = &rest[1..];
                let deps_trim = deps.trim_start();
                e.push(Scope::Text, &deps[..deps.len() - deps_trim.len()]);
                make_value(deps_trim, &mut e);
                continue;
            }
        }
        // Directives / other lines.
        let word_end = trimmed.find(|c: char| c.is_whitespace()).unwrap_or(trimmed.len());
        let word = &trimmed[..word_end];
        e.push(Scope::Text, &line[..line.len() - trimmed.len()]);
        if matches!(word, "include" | "ifeq" | "ifneq" | "ifdef" | "ifndef" | "else" | "endif" | "define" | "endef" | "export" | "unexport" | "override" | "vpath" | "-include" | "sinclude") {
            e.push(Scope::Keyword, word);
            make_value(&trimmed[word_end..], &mut e);
        } else {
            make_value(trimmed, &mut e);
        }
    }
    e.finish()
}

fn make_value(value: &str, e: &mut Emitter) {
    let mut cur = Cursor::new(value);
    while let Some(c) = cur.peek() {
        if c == '$' {
            make_variable(&mut cur, e);
        } else if c == '#' {
            let t = cur.take_line();
            e.push(Scope::Comment, t);
        } else {
            let t = cur.take_while(|c| c != '$' && c != '#');
            // Unquoted words are strings.
            let mut literal = String::new();
            for ch in t.chars() {
                if ch.is_whitespace() {
                    if !literal.is_empty() {
                        e.push(Scope::String, &literal);
                        literal.clear();
                    }
                    e.push(Scope::Text, &ch.to_string());
                } else {
                    literal.push(ch);
                }
            }
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
            }
        }
    }
}

fn make_variable(cur: &mut Cursor, e: &mut Emitter) {
    cur.advance(1);
    match cur.peek() {
        Some('(') | Some('{') => {
            let open = cur.peek().unwrap();
            let close = if open == '(' { ')' } else { '}' };
            cur.advance(1);
            e.push(Scope::Keyword, &format!("${}", open));
            let name = cur.take_while(|c| is_ident_char(c) || c == '.' || c == '-' || c == '@' || c == '<' || c == '^');
            e.push(Scope::Variable, name);
            let rest = cur.take_while(|c| c != close && c != '\n');
            e.push(Scope::Text, rest);
            if cur.peek() == Some(close) {
                cur.advance(1);
                e.push(Scope::Keyword, &close.to_string());
            }
        }
        Some(_) => {
            let start = cur.byte_pos() - 1;
            cur.advance(1);
            e.push(Scope::Variable, cur.slice(start));
        }
        None => e.push(Scope::Text, "$"),
    }
}

pub fn css(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    let mut in_block = false;
    while let Some(c) = cur.peek() {
        if cur.starts_with("/*") {
            let t = cur.take_until("*/");
            e.push(Scope::Comment, t);
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace());
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '"' || c == '\'' {
            quoted(&mut cur, &mut e, c, Scope::String, true);
            continue;
        }
        if c == '{' {
            in_block = true;
            cur.advance(1);
            e.push(Scope::Text, "{");
            continue;
        }
        if c == '}' {
            in_block = false;
            cur.advance(1);
            e.push(Scope::Text, "}");
            continue;
        }
        if !in_block {
            // Selectors.
            match c {
                '.' => {
                    cur.advance(1);
                    e.push(Scope::Function, ".");
                    let name = cur.take_while(|c| is_ident_char(c) || c == '-');
                    e.push(Scope::Constant, name);
                }
                '#' => {
                    let t = cur.take_while(|c| is_ident_char(c) || c == '-' || c == '#');
                    e.push(Scope::Function, t);
                }
                ':' => {
                    let colons = cur.take_while(|c| c == ':');
                    e.push(Scope::Function, colons);
                    let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == ',');
                    e.push(Scope::Keyword, name);
                }
                '@' => {
                    let t = cur.take_while(|c| is_ident_char(c) || c == '-' || c == '@');
                    e.push(Scope::Keyword, t);
                }
                '>' | '+' | '~' => {
                    cur.advance(1);
                    e.push(Scope::Keyword, &c.to_string());
                }
                c if is_ident_start(c) => {
                    let name = cur.take_while(|c| is_ident_char(c) || c == '-');
                    e.push(Scope::Variable, name);
                }
                '(' => {
                    // @media (feature: value)
                    let t = cur.take_while(|c| c != ')' && c != '{');
                    let mut inner = Cursor::new(t);
                    css_declaration_text(&mut inner, &mut e);
                }
                _ => {
                    cur.advance(1);
                    e.push(Scope::Text, &c.to_string());
                }
            }
            continue;
        }
        css_declaration_text(&mut cur, &mut e);
        if cur.peek() == Some('}') {
            continue;
        }
    }
    e.finish()
}

fn css_declaration_text(cur: &mut Cursor, e: &mut Emitter) {
    while let Some(c) = cur.peek() {
        if c == '}' {
            return;
        }
        if c == '"' || c == '\'' {
            quoted(cur, e, c, Scope::String, true);
            continue;
        }
        if cur.starts_with("/*") {
            let t = cur.take_until("*/");
            e.push(Scope::Comment, t);
            continue;
        }
        if c == '#' {
            let t = cur.take_while(|c| c.is_ascii_hexdigit() || c == '#');
            e.push(Scope::Support, t);
            continue;
        }
        if c.is_ascii_digit() || (c == '-' && cur.peek_at(1).map_or(false, |d| d.is_ascii_digit())) || (c == '.' && cur.peek_at(1).map_or(false, |d| d.is_ascii_digit())) {
            let t = cur.take_while(|c| c.is_ascii_alphanumeric() || c == '.' || c == '%' || c == '-');
            e.push(Scope::Constant, t);
            continue;
        }
        if is_ident_start(c) {
            let name = cur.take_while(|c| is_ident_char(c) || c == '-');
            if cur.peek() == Some('(') {
                e.push(Scope::Support, name);
            } else {
                e.push(Scope::Text, name);
            }
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        e.push(Scope::Text, cur.slice(start));
    }
}

const LUA_KEYWORDS: &[&str] = &[
    "break", "do", "else", "elseif", "end", "for", "function", "goto", "if", "in", "local",
    "repeat", "return", "then", "until", "while",
];
const LUA_BUILTINS: &[&str] = &[
    "print", "require", "pairs", "ipairs", "type", "tostring", "tonumber", "error", "assert",
    "pcall", "xpcall", "setmetatable", "getmetatable", "rawget", "rawset", "select", "unpack",
    "next", "load", "loadstring", "dofile", "collectgarbage", "rawequal", "rawlen",
];

pub fn lua(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    let mut prev_word = String::new();
    while let Some(c) = cur.peek() {
        if cur.starts_with("--[[") {
            let t = cur.take_until("]]");
            e.push(Scope::Comment, t);
            continue;
        }
        if cur.starts_with("--") {
            let t = cur.take_line();
            e.push(Scope::Comment, t);
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace());
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '"' || c == '\'' {
            quoted(&mut cur, &mut e, c, Scope::String, true);
            prev_word.clear();
            continue;
        }
        if cur.starts_with("[[") {
            let t = cur.take_until("]]");
            e.push(Scope::String, t);
            continue;
        }
        if c.is_ascii_digit() {
            let t = cur.take_while(|c| c.is_ascii_alphanumeric() || c == '.');
            e.push(Scope::Constant, t);
            prev_word.clear();
            continue;
        }
        if is_ident_start(c) {
            let w = cur.take_while(is_ident_char);
            let next = cur.rest().trim_start().chars().next();
            let scope = if matches!(w, "nil" | "true" | "false") {
                Scope::Constant
            } else if matches!(w, "and" | "or" | "not") {
                Scope::Text
            } else if LUA_KEYWORDS.contains(&w) {
                Scope::Keyword
            } else if prev_word == "function" {
                Scope::Function
            } else if next == Some('(') || next == Some('{') || next == Some('"') {
                if LUA_BUILTINS.contains(&w) { Scope::Support } else { Scope::Function }
            } else {
                Scope::Text
            };
            e.push(scope, w);
            prev_word = w.to_string();
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        e.push(Scope::Text, cur.slice(start));
        if c != '.' {
            prev_word.clear();
        }
    }
    e.finish()
}

const SQL_KEYWORDS: &[&str] = &[
    "select", "from", "where", "and", "or", "not", "insert", "into", "values", "update", "set",
    "delete", "create", "table", "drop", "alter", "add", "column", "primary", "key", "foreign",
    "references", "join", "left", "right", "inner", "outer", "full", "cross", "on", "as",
    "order", "by", "group", "having", "limit", "offset", "distinct", "union", "all", "exists",
    "in", "is", "null", "like", "between", "case", "when", "then", "else", "end", "asc",
    "desc", "index", "view", "if", "begin", "commit", "rollback", "transaction", "default",
    "constraint", "unique", "check", "with", "recursive", "returning", "truncate", "grant",
    "revoke", "cascade", "replace", "temporary", "temp", "explain", "analyze", "vacuum",
    "pragma", "using", "natural", "except", "intersect", "over", "partition", "window",
    "fetch", "first", "next", "rows", "only", "top", "count", "sum", "avg", "min", "max",
    "coalesce", "cast", "int", "integer", "varchar", "char", "text", "boolean", "date",
    "timestamp", "float", "double", "decimal", "numeric", "serial", "bigint", "smallint",
    "true", "false",
];

pub fn sql(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    let mut last_keyword = false;
    while let Some(c) = cur.peek() {
        if cur.starts_with("--") {
            let t = cur.take_line();
            e.push(Scope::Comment, t);
            continue;
        }
        if cur.starts_with("/*") {
            let t = cur.take_until("*/");
            e.push(Scope::Comment, t);
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace() && c != '\n');
            // Whitespace between two keywords keeps the keyword color.
            let next_word: String = cur.rest().chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
            let scope = if last_keyword && !next_word.is_empty() && SQL_KEYWORDS.contains(&next_word.to_lowercase().as_str()) && !ws.contains('\n') {
                Scope::Keyword
            } else {
                Scope::Text
            };
            e.push(scope, ws);
            if cur.peek() == Some('\n') {
                cur.advance(1);
                e.push(Scope::Text, "\n");
                last_keyword = false;
            }
            continue;
        }
        if c == '\'' || c == '"' {
            quoted(&mut cur, &mut e, c, Scope::String, true);
            last_keyword = false;
            continue;
        }
        if c.is_ascii_digit() {
            let t = cur.take_while(|c| c.is_ascii_alphanumeric() || c == '.');
            e.push(Scope::Constant, t);
            last_keyword = false;
            continue;
        }
        if is_ident_start(c) {
            let w = cur.take_while(is_ident_char);
            if matches!(w.to_lowercase().as_str(), "null" | "true" | "false") {
                e.push(Scope::Constant, w);
                last_keyword = false;
            } else if SQL_KEYWORDS.contains(&w.to_lowercase().as_str()) {
                e.push(Scope::Keyword, w);
                last_keyword = true;
            } else {
                e.push(Scope::Text, w);
                last_keyword = false;
            }
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        e.push(Scope::Text, cur.slice(start));
        last_keyword = false;
    }
    e.finish()
}

const RUBY_KEYWORDS: &[&str] = &[
    "alias", "begin", "break", "case", "class", "def", "defined?", "do", "else", "elsif",
    "end", "ensure", "for", "if", "in", "module", "next", "redo", "rescue", "retry", "return",
    "super", "then", "undef", "unless", "until", "when", "while", "yield", "private",
    "protected", "public", "lambda", "proc", "loop",
];
const RUBY_BUILTINS: &[&str] = &[
    "puts", "print", "p", "pp", "gets", "raise", "require_relative", "include", "extend",
    "format", "sprintf", "printf", "exit", "abort", "sleep", "rand", "loop", "catch", "throw",
    "freeze", "binding", "block_given?", "fail", "warn",
];

pub fn ruby(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    let mut prev = String::new();
    let mut class_header = false;
    while let Some(c) = cur.peek() {
        if c == '\n' {
            cur.advance(1);
            e.push(Scope::Text, "\n");
            class_header = false;
            prev.clear();
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace() && c != '\n');
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '#' {
            let t = cur.take_line();
            e.push(Scope::Comment, t);
            continue;
        }
        if c == '"' {
            ruby_string(&mut cur, &mut e);
            prev.clear();
            continue;
        }
        if c == '\'' {
            quoted(&mut cur, &mut e, '\'', Scope::String, false);
            prev.clear();
            continue;
        }
        if c == '@' {
            let start = cur.byte_pos();
            cur.take_while(|c| c == '@');
            e.push(Scope::Text, cur.slice(start));
            let name = cur.take_while(is_ident_char);
            e.push(Scope::Variable, name);
            prev.clear();
            continue;
        }
        if c == ':' && cur.peek_at(1).map_or(false, is_ident_start) && !prev.is_empty() || (c == ':' && cur.peek_at(1).map_or(false, is_ident_start) && prev.is_empty()) {
            if cur.peek_at(1) == Some(':') {
                cur.advance(2);
                e.push(Scope::Text, "::");
                continue;
            }
            let start = cur.byte_pos();
            cur.advance(1);
            cur.take_while(|c| is_ident_char(c) || c == '?' || c == '!');
            e.push(Scope::String, cur.slice(start));
            prev.clear();
            continue;
        }
        if c.is_ascii_digit() {
            let t = cur.take_while(|c| c.is_ascii_alphanumeric() || c == '.' || c == '_');
            e.push(Scope::Constant, t);
            prev.clear();
            continue;
        }
        if c == '|' && prev == "{" {
            cur.advance(1);
            e.push(Scope::Text, "|");
            let params = cur.take_while(|c| c != '|' && c != '\n');
            for (j, p) in params.split(',').enumerate() {
                if j > 0 {
                    e.push(Scope::Text, ",");
                }
                let t = p.trim();
                e.push(Scope::Text, &p[..p.len() - p.trim_start().len()]);
                e.push(Scope::Variable, t);
                e.push(Scope::Text, &p[p.trim_start().len() + (p.len() - p.trim_start().len())..]);
            }
            if cur.peek() == Some('|') {
                cur.advance(1);
                e.push(Scope::Text, "|");
            }
            prev.clear();
            continue;
        }
        if is_ident_start(c) {
            let start = cur.byte_pos();
            cur.take_while(is_ident_char);
            if matches!(cur.peek(), Some('?') | Some('!')) && cur.peek_at(1) != Some('=') {
                cur.advance(1);
            }
            let w = cur.slice(start);
            let next = cur.rest().chars().find(|c| *c != ' ');
            let scope = if matches!(w, "nil" | "true" | "false") {
                Scope::Constant
            } else if w == "self" {
                Scope::Variable
            } else if matches!(w, "and" | "or" | "not") {
                Scope::Text
            } else if RUBY_KEYWORDS.contains(&w) {
                if w == "class" || w == "module" {
                    class_header = true;
                }
                Scope::Keyword
            } else if prev == "def" {
                Scope::Function
            } else if prev == "class" || prev == "module" {
                Scope::Class
            } else if class_header && prev == "<" {
                Scope::String
            } else if prev == "." {
                if next == Some('(') || w == "new" { Scope::Function } else { Scope::Text }
            } else if w.chars().next().map_or(false, |c| c.is_uppercase()) {
                Scope::Class
            } else if RUBY_BUILTINS.contains(&w) {
                Scope::Support
            } else if prev.is_empty() || prev == "=" || prev == "(" || prev == "," {
                // Method call without parentheses at statement start.
                if prev.is_empty() && next.map_or(false, |n| n != '=' && n != '\n') && next != Some('.') {
                    Scope::Function
                } else {
                    Scope::Text
                }
            } else {
                Scope::Text
            };
            // Parameters of a def.
            let scope = if prev == "(" && scope == Scope::Text && class_header == false && last_def(&e) {
                Scope::Variable
            } else {
                scope
            };
            e.push(scope, w);
            prev = w.to_string();
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        let p = cur.slice(start);
        if class_header && p == "<" {
            e.push(Scope::Meta, p);
        } else {
            e.push(Scope::Text, p);
        }
        prev = p.to_string();
    }
    e.finish()
}

fn last_def(e: &Emitter) -> bool {
    e.current.iter().any(|(s, t)| *s == Scope::Keyword && t == "def")
}

fn ruby_string(cur: &mut Cursor, e: &mut Emitter) {
    cur.advance(1);
    e.push(Scope::Text, "\"");
    let mut literal = String::new();
    while let Some(c) = cur.peek() {
        if c == '\n' {
            break;
        }
        if c == '\\' {
            let start = cur.byte_pos();
            cur.advance(2);
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
                literal.clear();
            }
            e.push(Scope::Escape, cur.slice(start));
            continue;
        }
        if cur.starts_with("#{") {
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
                literal.clear();
            }
            cur.advance(2);
            e.push(Scope::Label, "#{");
            let inner = cur.take_while(|c| c != '}' && c != '\n').to_string();
            let mut icur = Cursor::new(&inner);
            while let Some(ic) = icur.peek() {
                if ic == '@' {
                    icur.advance(1);
                    e.push(Scope::Text, "@");
                    let n = icur.take_while(is_ident_char);
                    e.push(Scope::Variable, n);
                } else if is_ident_start(ic) {
                    let n = icur.take_while(is_ident_char);
                    e.push(Scope::Text, n);
                } else {
                    let s = icur.byte_pos();
                    icur.advance(1);
                    e.push(Scope::Text, icur.slice(s));
                }
            }
            if cur.peek() == Some('}') {
                cur.advance(1);
                e.push(Scope::Label, "}");
            }
            continue;
        }
        if c == '"' {
            cur.advance(1);
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
                literal.clear();
            }
            e.push(Scope::Text, "\"");
            return;
        }
        literal.push(c);
        cur.advance(1);
    }
    if !literal.is_empty() {
        e.push(Scope::String, &literal);
    }
}

pub fn markup(content: &str, html: bool) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    while let Some(c) = cur.peek() {
        if cur.starts_with("<!--") {
            let t = cur.take_until("-->");
            e.push(Scope::Comment, t);
            continue;
        }
        if cur.starts_with("<![CDATA[") {
            let t = cur.take_until("]]>");
            e.push(Scope::String, t);
            continue;
        }
        if c == '<' && (cur.starts_with("<!") || cur.starts_with("<?")) {
            let start = cur.byte_pos();
            cur.advance(2);
            e.push(Scope::Text, cur.slice(start));
            let name = cur.take_while(is_ident_char);
            e.push(Scope::Variable, name);
            markup_attributes(&mut cur, &mut e, html);
            continue;
        }
        if c == '<' && cur.peek_at(1).map_or(false, |d| is_ident_start(d) || d == '/') {
            let start = cur.byte_pos();
            cur.advance(1);
            if cur.peek() == Some('/') {
                cur.advance(1);
            }
            e.push(Scope::Text, cur.slice(start));
            let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == ':' || c == '.').to_string();
            e.push(Scope::Variable, &name);
            markup_attributes(&mut cur, &mut e, html);
            if html && (name.eq_ignore_ascii_case("script") || name.eq_ignore_ascii_case("style")) {
                let close = format!("</{}", name);
                let rest = cur.rest();
                let end = rest.to_lowercase().find(&close.to_lowercase()).unwrap_or(rest.len());
                let body = rest[..end].to_string();
                let n = body.chars().count();
                cur.advance(n);
                let inner = if name.eq_ignore_ascii_case("script") {
                    clike::highlight(&body, Language::JavaScript)
                } else {
                    css(&body)
                };
                for (li, line) in inner.into_iter().enumerate() {
                    if li > 0 {
                        e.push(Scope::Text, "\n");
                    }
                    for (scope, text) in line {
                        e.push(scope, &text);
                    }
                }
            }
            continue;
        }
        if c == '&' {
            let t = cur.take_while(|c| c != ';' && c != ' ' && c != '<' && c != '\n');
            if cur.peek() == Some(';') {
                cur.advance(1);
                e.push(Scope::Constant, &format!("{};", t));
            } else {
                e.push(Scope::Text, t);
            }
            continue;
        }
        let t = cur.take_while(|c| c != '<' && c != '&');
        if t.is_empty() {
            let start = cur.byte_pos();
            cur.advance(1);
            e.push(Scope::Text, cur.slice(start));
        } else {
            e.push(Scope::Text, t);
        }
    }
    e.finish()
}

fn markup_attributes(cur: &mut Cursor, e: &mut Emitter, html: bool) {
    while let Some(c) = cur.peek() {
        if c == '>' {
            cur.advance(1);
            e.push(Scope::Text, ">");
            return;
        }
        if cur.starts_with("/>") || cur.starts_with("?>") {
            cur.advance(2);
            e.push(Scope::Text, if c == '/' { "/>" } else { "?>" });
            return;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace());
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '"' || c == '\'' {
            quoted(cur, e, c, Scope::String, false);
            continue;
        }
        if is_ident_start(c) {
            let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == ':' || c == '.');
            let scope = if html && name.eq_ignore_ascii_case("id") { Scope::Function } else { Scope::Constant };
            e.push(scope, name);
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        e.push(Scope::Text, cur.slice(start));
    }
}
