pub fn ruby(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    let mut prev = String::new();
    let mut class_header = false;
    while let Some(c) = cur.peek() {
        if c == '\n' {
            cur.advance(1);
            e.push(Scope::Text, "\n");
            class_header = false;
            prev.clear();
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace() && c != '\n');
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '#' {
            let t = cur.take_line();
            e.push(Scope::Comment, t);
            continue;
        }
        if c == '"' {
            ruby_string(&mut cur, &mut e);
            prev.clear();
            continue;
        }
        if c == '\'' {
            quoted(&mut cur, &mut e, '\'', Scope::String, false);
            prev.clear();
            continue;
        }
        if c == '@' {
            let start = cur.byte_pos();
            cur.take_while(|c| c == '@');
            e.push(Scope::Text, cur.slice(start));
            let name = cur.take_while(is_ident_char);
            e.push(Scope::Variable, name);
            prev.clear();
            continue;
        }
        if c == ':' && cur.peek_at(1).map_or(false, is_ident_start) && !prev.is_empty() || (c == ':' && cur.peek_at(1).map_or(false, is_ident_start) && prev.is_empty()) {
            if cur.peek_at(1) == Some(':') {
                cur.advance(2);
                e.push(Scope::Text, "::");
                continue;
            }
            let start = cur.byte_pos();
            cur.advance(1);
            cur.take_while(|c| is_ident_char(c) || c == '?' || c == '!');
            e.push(Scope::String, cur.slice(start));
            prev.clear();
            continue;
        }
        if c.is_ascii_digit() {
            let t = cur.take_while(|c| c.is_ascii_alphanumeric() || c == '.' || c == '_');
            e.push(Scope::Constant, t);
            prev.clear();
            continue;
        }
        if c == '|' && prev == "{" {
            cur.advance(1);
            e.push(Scope::Text, "|");
            let params = cur.take_while(|c| c != '|' && c != '\n');
            for (j, p) in params.split(',').enumerate() {
                if j > 0 {
                    e.push(Scope::Text, ",");
                }
                let t = p.trim();
                e.push(Scope::Text, &p[..p.len() - p.trim_start().len()]);
                e.push(Scope::Variable, t);
                e.push(Scope::Text, &p[p.trim_start().len() + (p.len() - p.trim_start().len())..]);
            }
            if cur.peek() == Some('|') {
                cur.advance(1);
                e.push(Scope::Text, "|");
            }
            prev.clear();
            continue;
        }
        if is_ident_start(c) {
            let start = cur.byte_pos();
            cur.take_while(is_ident_char);
            if matches!(cur.peek(), Some('?') | Some('!')) && cur.peek_at(1) != Some('=') {
                cur.advance(1);
            }
            let w = cur.slice(start);
            let next = cur.rest().chars().find(|c| *c != ' ');
            let scope = if matches!(w, "nil" | "true" | "false") {
                Scope::Constant
            } else if w == "self" {
                Scope::Variable
            } else if matches!(w, "and" | "or" | "not") {
                Scope::Text
            } else if RUBY_KEYWORDS.contains(&w) {
                if w == "class" || w == "module" {
                    class_header = true;
                }
                Scope::Keyword
            } else if prev == "def" {
                Scope::Function
            } else if prev == "class" || prev == "module" {
                Scope::Class
            } else if class_header && prev == "<" {
                Scope::String
            } else if prev == "." {
                if next == Some('(') || w == "new" { Scope::Function } else { Scope::Text }
            } else if w.chars().next().map_or(false, |c| c.is_uppercase()) {
                Scope::Class
            } else if RUBY_BUILTINS.contains(&w) {
                Scope::Support
            } else if prev.is_empty() || prev == "=" || prev == "(" || prev == "," {
                // Method call without parentheses at statement start.
                if prev.is_empty() && next.map_or(false, |n| n != '=' && n != '\n') && next != Some('.') {
                    Scope::Function
                } else {
                    Scope::Text
                }
            } else {
                Scope::Text
            };
            // Parameters of a def.
            let scope = if prev == "(" && scope == Scope::Text && class_header == false && last_def(&e) {
                Scope::Variable
            } else {
                scope
            };
            e.push(scope, w);
            prev = w.to_string();
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        let p = cur.slice(start);
        if class_header && p == "<" {
            e.push(Scope::Meta, p);
        } else {
            e.push(Scope::Text, p);
        }
        prev = p.to_string();
    }
    e.finish()
}

fn last_def(e: &Emitter) -> bool {
    e.current.iter().any(|(s, t)| *s == Scope::Keyword && t == "def")
}

fn ruby_string(cur: &mut Cursor, e: &mut Emitter) {
    cur.advance(1);
    e.push(Scope::Text, "\"");
    let mut literal = String::new();
    while let Some(c) = cur.peek() {
        if c == '\n' {
            break;
        }
        if c == '\\' {
            let start = cur.byte_pos();
            cur.advance(2);
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
                literal.clear();
            }
            e.push(Scope::Escape, cur.slice(start));
            continue;
        }
        if cur.starts_with("#{") {
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
                literal.clear();
            }
            cur.advance(2);
            e.push(Scope::Label, "#{");
            let inner = cur.take_while(|c| c != '}' && c != '\n').to_string();
            let mut icur = Cursor::new(&inner);
            while let Some(ic) = icur.peek() {
                if ic == '@' {
                    icur.advance(1);
                    e.push(Scope::Text, "@");
                    let n = icur.take_while(is_ident_char);
                    e.push(Scope::Variable, n);
                } else if is_ident_start(ic) {
                    let n = icur.take_while(is_ident_char);
                    e.push(Scope::Text, n);
                } else {
                    let s = icur.byte_pos();
                    icur.advance(1);
                    e.push(Scope::Text, icur.slice(s));
                }
            }
            if cur.peek() == Some('}') {
                cur.advance(1);
                e.push(Scope::Label, "}");
            }
            continue;
        }
        if c == '"' {
            cur.advance(1);
            if !literal.is_empty() {
                e.push(Scope::String, &literal);
                literal.clear();
            }
            e.push(Scope::Text, "\"");
            return;
        }
        literal.push(c);
        cur.advance(1);
    }
    if !literal.is_empty() {
        e.push(Scope::String, &literal);
    }
}

pub fn markup(content: &str, html: bool) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    while let Some(c) = cur.peek() {
        if cur.starts_with("<!--") {
            let t = cur.take_until("-->");
            e.push(Scope::Comment, t);
            continue;
        }
        if cur.starts_with("<![CDATA[") {
            let t = cur.take_until("]]>");
            e.push(Scope::String, t);
            continue;
        }
        if c == '<' && (cur.starts_with("<!") || cur.starts_with("<?")) {
            let start = cur.byte_pos();
            cur.advance(2);
            e.push(Scope::Text, cur.slice(start));
            let name = cur.take_while(is_ident_char);
            e.push(Scope::Variable, name);
            markup_attributes(&mut cur, &mut e, html);
            continue;
        }
        if c == '<' && cur.peek_at(1).map_or(false, |d| is_ident_start(d) || d == '/') {
            let start = cur.byte_pos();
            cur.advance(1);
            if cur.peek() == Some('/') {
                cur.advance(1);
            }
            e.push(Scope::Text, cur.slice(start));
            let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == ':' || c == '.').to_string();
            e.push(Scope::Variable, &name);
            markup_attributes(&mut cur, &mut e, html);
            if html && (name.eq_ignore_ascii_case("script") || name.eq_ignore_ascii_case("style")) {
                let close = format!("</{}", name);
                let rest = cur.rest();
                let end = rest.to_lowercase().find(&close.to_lowercase()).unwrap_or(rest.len());
                let body = rest[..end].to_string();
                let n = body.chars().count();
                cur.advance(n);
                let inner = if name.eq_ignore_ascii_case("script") {
                    clike::highlight(&body, Language::JavaScript)
                } else {
                    css(&body)
                };
                for (li, line) in inner.into_iter().enumerate() {
                    if li > 0 {
                        e.push(Scope::Text, "\n");
                    }
                    for (scope, text) in line {
                        e.push(scope, &text);
                    }
                }
            }
            continue;
        }
        if c == '&' {
            let t = cur.take_while(|c| c != ';' && c != ' ' && c != '<' && c != '\n');
            if cur.peek() == Some(';') {
                cur.advance(1);
                e.push(Scope::Constant, &format!("{};", t));
            } else {
                e.push(Scope::Text, t);
            }
            continue;
        }
        let t = cur.take_while(|c| c != '<' && c != '&');
        if t.is_empty() {
            let start = cur.byte_pos();
            cur.advance(1);
            e.push(Scope::Text, cur.slice(start));
        } else {
            e.push(Scope::Text, t);
        }
    }
    e.finish()
}

fn markup_attributes(cur: &mut Cursor, e: &mut Emitter, html: bool) {
    while let Some(c) = cur.peek() {
        if c == '>' {
            cur.advance(1);
            e.push(Scope::Text, ">");
            return;
        }
        if cur.starts_with("/>") || cur.starts_with("?>") {
            cur.advance(2);
            e.push(Scope::Text, if c == '/' { "/>" } else { "?>" });
            return;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace());
            e.push(Scope::Text, ws);
            continue;
        }
        if c == '"' || c == '\'' {
            quoted(cur, e, c, Scope::String, false);
            continue;
        }
        if is_ident_start(c) {
            let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == ':' || c == '.');
            let scope = if html && name.eq_ignore_ascii_case("id") { Scope::Function } else { Scope::Constant };
            e.push(scope, name);
            continue;
        }
        let start = cur.byte_pos();
        cur.advance(1);
        e.push(Scope::Text, cur.slice(start));
    }
}
