new='''pub fn css(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    let mut cur = Cursor::new(content);
    // Stack of open blocks: true when the block contains rules (selectors).
    let mut blocks: Vec<bool> = Vec::new();
    let mut at_rule = false;
    let in_declarations = |blocks: &Vec<bool>| blocks.last() == Some(&false);
    while let Some(c) = cur.peek() {
        if cur.starts_with("/*") {
            let t = cur.take_until("*/");
            e.push(Scope::Comment, t);
            continue;
        }
        if c.is_whitespace() {
            let ws = cur.take_while(|c| c.is_whitespace());
            // In selectors, spaces take the scope of the preceding token.
            let scope = match e.current.last() {
                Some((s, _)) if !in_declarations(&blocks) && !ws.contains('\\n') && !matches!(s, Scope::Comment) => *s,
                _ => Scope::Text,
            };
            e.push(scope, ws);
            continue;
        }
        if c == '"' || c == '\\'' {
            quoted(&mut cur, &mut e, c, Scope::String, true);
            continue;
        }
        if c == '{' {
            e.restyle_trailing_whitespace(Scope::Text);
            blocks.push(at_rule);
            at_rule = false;
            cur.advance(1);
            e.push(Scope::Text, "{");
            continue;
        }
        if c == '}' {
            blocks.pop();
            cur.advance(1);
            e.push(Scope::Text, "}");
            continue;
        }
        if !in_declarations(&blocks) {
            // Selectors.
            match c {
                '.' => {
                    cur.advance(1);
                    e.push(Scope::Function, ".");
                    let name = cur.take_while(|c| is_ident_char(c) || c == '-');
                    e.push(Scope::Constant, name);
                }
                '#' => {
                    let t = cur.take_while(|c| is_ident_char(c) || c == '-' || c == '#');
                    e.push(Scope::Function, t);
                }
                ':' => {
                    let colons = cur.take_while(|c| c == ':');
                    e.push(Scope::Function, colons);
                    let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == ',');
                    e.push(Scope::Keyword, name);
                }
                '@' => {
                    let t = cur.take_while(|c| is_ident_char(c) || c == '-' || c == '@');
                    e.push(Scope::Keyword, t);
                    at_rule = true;
                }
                '>' | '+' | '~' => {
                    e.restyle_trailing_whitespace(Scope::Keyword);
                    cur.advance(1);
                    e.push(Scope::Keyword, &c.to_string());
                }
                ',' => {
                    cur.advance(1);
                    e.push(Scope::Text, ",");
                }
                c if is_ident_start(c) || c == '*' => {
                    let name = cur.take_while(|c| is_ident_char(c) || c == '-' || c == '*');
                    e.push(Scope::Variable, name);
                }
                '(' => {
                    // @media (feature: value)
                    cur.advance(1);
                    e.push(Scope::Text, "(");
                    let t = cur.take_while(|c| c != ')' && c != '{');
                    let mut inner = Cursor::new(t);
                    css_declaration_text(&mut inner, &mut e);
                    if cur.peek() == Some(')') {
                        cur.advance(1);
                        e.push(Scope::Text, ")");
                    }
                }
                _ => {
                    cur.advance(1);
                    e.push(Scope::Text, &c.to_string());
                }
            }
            continue;
        }
        css_declaration_text(&mut cur, &mut e);
    }
    e.finish()
}

