#!/usr/bin/env python3
"""Module docstring.

Multi-line.
"""
import re
import subprocess as sp
from pathlib import Path

PATTERN = re.compile(r"^(?P<key>\w+)\s*=\s*(?P<value>.*)$")
DEFAULTS = {"debug": False, "level": 3}


class Parser(object):
    """Parse simple config files."""

    count = 0

    def __init__(self, path: Path, *, strict=True):
        self.path = path
        self._strict = strict
        Parser.count += 1

    def __repr__(self):
        return f"Parser({self.path!r})"

    def parse(self):
        result = dict(DEFAULTS)
        for lineno, line in enumerate(self.path.read_text().splitlines(), 1):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            m = PATTERN.match(line)
            if m is None:
                if self._strict:
                    raise ValueError(f"line {lineno}: bad syntax")
                continue
            result[m.group("key")] = m.group("value")
        return result


def run(cmd: list[str]) -> int:
    proc = sp.run(cmd, capture_output=True, text=True, check=False)
    print(proc.stdout, end="")
    return proc.returncode


if __name__ == "__main__":
    p = Parser(Path("config.ini"))
    print(p.parse())
EOF
