                    'd' | 'D' | 'w' | 'W' | 's' | 'S' => Scope::Constant,
                    'b' | 'B' | 'A' | 'Z' => Scope::Keyword,
                    _ => Scope::Escape,
                };
                e.push(scope, &text);
                i += 2;
            }
            '.' => {
                flush(&mut literal, e);
                e.push(Scope::Constant, ".");
                i += 1;
            }
            '^' | '$' => {
                flush(&mut literal, e);
                e.push(Scope::Keyword, &c.to_string());
                i += 1;
            }
            '*' | '+' | '?' | '|' => {
                flush(&mut literal, e);
                e.push(Scope::Text, &c.to_string());
                i += 1;
            }
            '{' => {
                let end = chars[i..].iter().position(|d| *d == '}');
                match end {
                    Some(len) if chars[i + 1..i + len].iter().all(|d| d.is_ascii_digit() || *d == ',') && len > 1 => {
                        flush(&mut literal, e);
                        let text: String = chars[i..=i + len].iter().collect();
                        e.push(Scope::Text, &text);
                        i += len + 1;
                    }
                    _ => {
                        literal.push(c);
                        i += 1;
                    }
                }
            }
            '[' => {
                flush(&mut literal, e);
                e.push(Scope::Constant, "[");
                i += 1;
                if i < chars.len() && chars[i] == '^' {
                    e.push(Scope::Text, "^");
                    i += 1;
                }
                let mut class = String::new();
                while i < chars.len() {
                    if chars[i] == '\\\\' && i + 1 < chars.len() {
                        class.push(chars[i]);
                        class.push(chars[i + 1]);
                        i += 2;
                        continue;
                    }
                    if chars[i] == '[' && chars.get(i + 1) == Some(&':') {
                        while i < chars.len() {
                            class.push(chars[i]);
                            if chars[i] == ']' {
                                i += 1;
                                break;
                            }
                            i += 1;
                        }
                        continue;
                    }
                    class.push(chars[i]);
                    i += 1;
                    if chars[i - 1] == ']' {
                        break;
                    }
                }
                e.push(Scope::Constant, &class);
            }
            _ => {
                literal.push(c);
                i += 1;
            }
        }
    }
    flush(&mut literal, e);
}

