src=open('src/ui/result_list.rs').read()
old_start=src.index('    pub fn draw(&mut self, frame: &mut Frame, area: Rect, theme: &Theme) {')
old_end=src.index('/// Prepare a fragment of a matched line')
new='''    pub fn draw(&mut self, frame: &mut Frame, area: Rect, theme: &Theme) {
        let selected = self.selected_item_index();
        let total_items: usize = self.entries.iter().map(|e| e.matches.len() + 1).sum();

        // The list offset is managed manually: when moving down the selected
        // entry ends up on the last row, when moving up the entry preceding
        // the selection (e.g. the file name) is kept visible.
        let block = Block::bordered().border_type(BorderType::Rounded);
        let height = block.inner(area).height as usize;
        let mut offset = self.state.offset();
        if let Some(index) = selected {
            if index >= offset + height {
                offset = (index + 1).saturating_sub(height);
            }
            if index <= offset {
                offset = index.saturating_sub(1);
            }
        }
        offset = offset.min(total_items.saturating_sub(1));
        if total_items == 0 {
            offset = 0;
        }

        // Only the visible items are built.
        let mut items = Vec::with_capacity(height);
        let mut index = 0usize;
        'files: for file in &self.entries {
            let file_items = file.matches.len() + 1;
            if index + file_items <= offset {
                index += file_items;
                continue;
            }
            if index >= offset {
                items.push(ListItem::new(Line::from(Span::styled(
                    file.name.clone(),
                    theme.file_name_style(),
                ))));
            }
            index += 1;
            for m in &file.matches {
                if index >= offset {
                    if items.len() >= height {
                        break 'files;
                    }
                    let mut item = ListItem::new(match_line(m, theme));
                    if selected == Some(index) {
                        item = item.style(theme.selected_style());
                    }
                    items.push(item);
                }
                index += 1;
            }
            if items.len() >= height {
                break;
            }
        }

        self.state.select(None);
        *self.state.offset_mut() = 0;
        let mut state = ListState::default();
        let list = List::new(items).block(block).style(Style::default());
        frame.render_stateful_widget(list, area, &mut state);
        *self.state.offset_mut() = offset;
    }
}

/// Render a matched line: line number followed by the text with the matched
/// fragments highlighted.
fn match_line<'a>(m: &'a crate::ig::Match, theme: &Theme) -> Line<'a> {
    let mut spans = vec![Span::styled(
        format!(" {}: ", m.line_number),
        theme.line_number_style(),
    )];
    let text = &m.text;
    let mut pos = 0;
    for &(start, end) in &m.ranges {
        let start = start.min(text.len());
        let end = end.min(text.len());
        if start < pos || end <= start {
            continue;
        }
        if !text.is_char_boundary(start) || !text.is_char_boundary(end) {
            continue;
        }
        if pos < start {
            spans.push(Span::raw(tabs(&text[pos..start])));
        }
        spans.push(Span::styled(tabs(&text[start..end]), theme.match_style()));
        pos = end;
    }
    if pos < text.len() {
        spans.push(Span::raw(tabs(&text[pos..])));
    }
    Line::from(spans)
}

