new='''pub fn yaml(content: &str) -> Vec<Vec<Segment>> {
    let mut e = Emitter::new();
    // Indentation of the block scalar currently being read (if any).
    let mut block_scalar: Option<usize> = None;
    for (i, line) in content.split('\\n').enumerate() {
        if i > 0 {
            e.push(Scope::Text, "\\n");
        }
        let trimmed = line.trim_start();
        let indent = line.len() - trimmed.len();
        if let Some(parent) = block_scalar {
            if trimmed.is_empty() || indent > parent {
                e.push(Scope::String, line);
                continue;
            }
            block_scalar = None;
        }
        e.push(Scope::Text, &line[..indent]);
        if trimmed.starts_with('#') {
            e.push(Scope::Comment, trimmed);
            continue;
        }
        let mut rest = trimmed;
        if rest == "---" || rest == "..." {
            e.push(Scope::Text, rest);
            continue;
        }
        if rest.starts_with("- ") || rest == "-" || rest.starts_with("? ") || rest.starts_with(": ") {
            e.push(Scope::Text, &rest[..1]);
            rest = &rest[1..];
            let after = rest.trim_start();
            e.push(Scope::Text, &rest[..rest.len() - after.len()]);
            rest = after;
            if trimmed.starts_with('?') || trimmed.starts_with(':') {
                yaml_value(rest, &mut e, indent, &mut block_scalar);
                continue;
            }
        }
        // key: value
        if let Some(colon) = find_key_colon(rest) {
            let key = &rest[..colon];
            if !key.is_empty() && !key.starts_with('"') && !key.starts_with('\\'') && !key.starts_with('[') && !key.starts_with('{') {
                let scope = if yaml_constant(key) || key == "<<" { Scope::Constant } else { Scope::Variable };
                e.push(scope, key);
                e.push(Scope::Text, ":");
                rest = &rest[colon + 1..];
            } else if key.starts_with('"') || key.starts_with('\\'') {
                e.push(Scope::Text, &key[..1]);
                e.push(Scope::String, &key[1..key.len().saturating_sub(1)]);
                e.push(Scope::Text, &key[key.len().saturating_sub(1)..]);
                e.push(Scope::Text, ":");
                rest = &rest[colon + 1..];
            }
        }
        yaml_value(rest, &mut e, indent, &mut block_scalar);
    }
    e.finish()
}

fn yaml_constant(value: &str) -> bool {
    matches!(
        value,
        "true" | "false" | "null" | "~" | "yes" | "no" | "on" | "off" | "True" | "False" | "Null"
            | "TRUE" | "FALSE" | "NULL" | "Yes" | "No" | "On" | "Off" | "YES" | "NO" | "ON" | "OFF"
    )
}

