new='''fn yaml_value(rest: &str, e: &mut Emitter, indent: usize, block_scalar: &mut Option<usize>) {
    let value = rest.trim_start();
    e.push(Scope::Text, &rest[..rest.len() - value.len()]);
    if value.is_empty() {
        return;
    }
    // Trailing comment.
    let (value, comment) = match value.find(" #") {
        Some(i) if !value.starts_with('"') && !value.starts_with('\\'') => (&value[..i], &value[i..]),
        _ => (value, ""),
    };
    let mut cur = Cursor::new(value);
    // Properties: anchors, tags.
    loop {
        match cur.peek() {
            Some('&') | Some('!') => {
                let c = cur.peek().unwrap();
                if c == '&' {
                    cur.advance(1);
                    e.push(Scope::Keyword, "&");
                    let name = cur.take_while(|c| !c.is_whitespace());
                    e.push(Scope::Text, name);
                } else {
                    let tag = cur.take_while(|c| !c.is_whitespace());
                    e.push(Scope::Keyword, tag);
                }
                let ws = cur.take_while(|c| c.is_whitespace());
                e.push(Scope::Text, ws);
            }
            _ => break,
        }
    }
    let value = cur.rest();
    if value.is_empty() {
        // nothing more
    } else if value.starts_with('*') {
        e.push(Scope::Keyword, "*");
        e.push(Scope::Variable, &value[1..]);
    } else if value == "|" || value == ">" || value.starts_with("|-") || value.starts_with(">-") || value.starts_with("|+") || value.starts_with(">+") {
        e.push(Scope::Keyword, value);
        *block_scalar = Some(indent);
    } else if value.starts_with('"') || value.starts_with('\\'') {
        let mut qcur = Cursor::new(value);
        let q = value.chars().next().unwrap();
        quoted(&mut qcur, e, q, Scope::String, q == '"');
        e.push(Scope::Text, qcur.rest());
    } else if yaml_constant(value) || number_like(value) {
        e.push(Scope::Constant, value);
    } else if value.starts_with('[') || value.starts_with('{') {
        // Flow collections: scalars are strings/constants, punctuation plain.
        let mut fcur = Cursor::new(value);
        while let Some(c) = fcur.peek() {
            if matches!(c, '[' | ']' | '{' | '}' | ',' | ':') || c.is_whitespace() {
                let s = fcur.byte_pos();
                fcur.advance(1);
                e.push(Scope::Text, fcur.slice(s));
            } else if c == '"' || c == '\\'' {
                quoted(&mut fcur, e, c, Scope::String, c == '"');
            } else {
                let item = fcur.take_while(|c| !matches!(c, '[' | ']' | '{' | '}' | ',' | ':'));
                let scope = if yaml_constant(item.trim()) || number_like(item.trim()) { Scope::Constant } else { Scope::String };
                e.push(scope, item);
            }
        }
    } else {
        e.push(Scope::String, value);
    }
    if !comment.is_empty() {
        let c = comment.trim_start();
        e.push(Scope::Text, &comment[..comment.len() - c.len()]);
        e.push(Scope::Comment, c);
    }
}

