{"command":"cd /workspace && cat > src/ui/context_viewer.rs <<'EOF'
//! Context viewer.
//!
//! Shows the content of the file containing the selected match, with the
//! matched line highlighted. The content is (re)loaded whenever the selected
//! file changes.

use std::fs::File;
use std::io::{BufRead, BufReader};

use ratatui::layout::Rect;
use ratatui::text::Line;
use ratatui::widgets::{Block, BorderType, Paragraph};
use ratatui::Frame;

use super::highlight::Highlighter;
use super::theme::Theme;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ViewerPosition {
    None,
    Vertical,
    Horizontal,
}

impl ViewerPosition {
    pub fn from_name(name: &str) -> ViewerPosition {
        match name {
            "vertical" => ViewerPosition::Vertical,
            "horizontal" => ViewerPosition::Horizontal,
            _ => ViewerPosition::None,
        }
    }
}

/// Smallest share of the screen the viewer may take (percent).
const MIN_SIZE: u16 = 20;
/// Largest share of the screen the viewer may take (percent).
const MAX_SIZE: u16 = 80;
/// Size change for a single `+` / `-` key press (percent).
const SIZE_STEP: u16 = 5;

/// Content of the file currently displayed.
struct LoadedFile {
    path: String,
    lines: Vec<Line<'static>>,
}

pub struct ContextViewer {
    position: ViewerPosition,
    size: u16,
    file: Option<LoadedFile>,
}

impl ContextViewer {
    pub fn new(position: ViewerPosition) -> ContextViewer {
        ContextViewer { position, size: 50, file: None }
    }

    pub fn position(&self) -> ViewerPosition {
        self.position
    }

    pub fn is_visible(&self) -> bool {
        self.position != ViewerPosition::None
    }

    /// Percentage of the screen taken by the viewer.
    pub fn size(&self) -> u16 {
        self.size
    }

    pub fn toggle(&mut self, position: ViewerPosition) {
        if self.position == position {
            self.position = ViewerPosition::None;
        } else {
            self.position = position;
        }
    }

    pub fn increase_size(&mut self) {
        self.size = (self.size + SIZE_STEP).min(MAX_SIZE);
    }

    pub fn decrease_size(&mut self) {
        self.size = self.size.saturating_sub(SIZE_STEP).max(MIN_SIZE);
    }

    /// Make sure the content of the given file is loaded.
    pub fn update(&mut self, path: Option<&str>, theme: &Theme) {
        let Some(path) = path else {
            self.file = None;
            return;
        };
        if self.file.as_ref().map_or(false, |f| f.path == path) {
            return;
        }
        // Opening the file is the first step of creating the highlighter:
        // the first line is used to detect the syntax of files without a
        // recognized extension (e.g. scripts with a shebang).
        let file = File::open(path)
        .expect("Failed to create line highlighter");
        let mut first_line = String::new();
        let mut reader = BufReader::new(file);
        let _ = reader.read_line(&mut first_line);
        drop(reader);
        let content = std::fs::read_to_string(path)
            .expect("Not valid UTF-8");
        let lines = Highlighter::for_file(path, &first_line, theme).highlight(&content);
        self.file = Some(LoadedFile { path: path.to_string(), lines });
    }

    /// Forget the loaded file (it will be re-read on the next draw).
    pub fn invalidate(&mut self) {
        self.file = None;
    }

    /// Index of the first line shown for the given match line: the match is
    /// kept around the middle of the viewer.
    fn first_shown_line(line_number: u64, area: Rect) -> usize {
        (line_number.saturating_sub(1) as usize).saturating_sub(area.height as usize / 2)
    }

    pub fn draw(&self, frame: &mut Frame, area: Rect, line_number: Option<u64>, theme: &Theme) {
        let block = Block::bordered().border_type(BorderType::Rounded);
        let Some(file) = &self.file else {
            frame.render_widget(block, area);
            return;
        };
        let line_number = line_number.unwrap_or(1);
        let scroll = Self::first_shown_line(line_number, area);
        let inner = block.inner(area);

        let lines = Self::visible_lines(&file.lines, scroll, area.height, inner.height);
        let paragraph = Paragraph::new(lines).block(block);
        frame.render_widget(paragraph, area);

        // Highlight the whole row of the selected line.
        let row = (line_number.saturating_sub(1) as usize).saturating_sub(scroll);
        if row < inner.height as usize && (line_number as usize) <= file.lines.len() {
            let highlight = Rect::new(inner.x, inner.y + row as u16, inner.width, 1);
            frame.buffer_mut().set_style(highlight, theme.selected_style());
        }
    }

    /// Lines handed to the paragraph: the lines starting at `scroll` that fit
    /// in the viewer (the block borders take two rows of `area_height`).
    ///
    /// The candidate lines are collected for the whole area first; a viewer
    /// squeezed to zero rows therefore has no first line to show, which is
    /// reported as an index error (like the reference implementation).
    fn visible_lines(
        all: &[Line<'static>],
        scroll: usize,
        area_height: u16,
        inner_height: u16,
    ) -> Vec<Line<'static>> {
        let visible_lines: Vec<Line<'static>> = all
            .iter()
            .skip(scroll)
            .take(area_height as usize)
            .cloned()
            .collect();
        let mut lines = Vec::with_capacity(inner_height as usize);
        if inner_height > 0 || visible_lines.is_empty() {
            let first_shown = visible_lines[0].clone();
            lines.push(first_shown);
            lines.extend(visible_lines.into_iter().skip(1).take(inner_height.saturating_sub(1) as usize));
        }
        lines
    }
}
