    pub fn invalidate(&mut self) {
        self.file = None;
    }

    /// Index of the first line shown for the given match line: the match is
    /// kept around the middle of the viewer.
    fn first_shown_line(line_number: u64, area: Rect) -> usize {
        (line_number.saturating_sub(1) as usize).saturating_sub(area.height as usize / 2)
    }

    pub fn draw(&self, frame: &mut Frame, area: Rect, line_number: Option<u64>, theme: &Theme) {
        let block = Block::bordered().border_type(BorderType::Rounded);
        let Some(file) = &self.file else {
            frame.render_widget(block, area);
            return;
        };
        let line_number = line_number.unwrap_or(1);
        let scroll = Self::first_shown_line(line_number, area);
        let inner = block.inner(area);

        let lines = Self::visible_lines(&file.lines, scroll, area.height, inner.height);
        let paragraph = Paragraph::new(lines).block(block);
        frame.render_widget(paragraph, area);

        // Highlight the whole row of the selected line.
        let row = (line_number.saturating_sub(1) as usize).saturating_sub(scroll);
        if row < inner.height as usize && (line_number as usize) <= file.lines.len() {
            let highlight = Rect::new(inner.x, inner.y + row as u16, inner.width, 1);
            frame.buffer_mut().set_style(highlight, theme.selected_style());
        }
    }

    /// Lines handed to the paragraph: the lines starting at `scroll` that fit
    /// in the viewer (the block borders take two rows of `area_height`).
    ///
    /// The candidate lines are collected for the whole area first; a viewer
    /// squeezed to zero rows therefore has no first line to show, which is
    /// reported as an index error (like the reference implementation).
    fn visible_lines(
        all: &[Line<'static>],
        scroll: usize,
        area_height: u16,
        inner_height: u16,
    ) -> Vec<Line<'static>> {
        let visible_lines: Vec<Line<'static>> = all
            .iter()
            .skip(scroll)
            .take(area_height as usize)
            .cloned()
            .collect();
        let mut lines = Vec::with_capacity(inner_height as usize);
        if inner_height > 0 || visible_lines.is_empty() {
            let first_shown = visible_lines[0].clone();
            lines.push(first_shown);
            lines.extend(visible_lines.into_iter().skip(1).take(inner_height.saturating_sub(1) as usize));
        }
        lines
    }
}
